-- GENERATED by tools/make_low_detail.py from api_frame_idx_slotS_mM.sql: do
-- not edit; edit the full-detail template and run it again. Low detail: the
-- view api_frame_idx_slot<slot>_m<map>_low computes even columns only and
-- draws each twice (see the tool's docstring).
-- Template of the frame view api_frame_idx_slot<slot>_m<map> (one per map and
-- player slot). doom.create_frame_views() fills in {name}, {map_id}, {slot}
-- and {thing_id} (the slot's player start, things.id) and creates the views.
-- The renderer: LBDoom's sql/renderer.sql (Ilia Chibaev, 2026-11-17, GPL-2.0),
-- converted for our views (map and player folded in, skill from mp_match, pose
-- from the caller's seat, palette indices instead of RGB, only seated or alive
-- other players drawn) by the converter of doomapp/lbdoom.py (Git history).
CREATE OR REPLACE FUNCTION doom.frame_view_template_api_frame_idx_low()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $template$SELECT $view$CREATE OR REPLACE VIEW doom.{name} AS
-- The one-row CTEs that are pure constants or the pose (render_context, pos,
-- render_settings, cam) are NOT MATERIALIZED: Postgres materializes a CTE
-- that is referenced more than once, and a materialized one is opaque to
-- the planner -- every reference became a nested loop over a one-row scan,
-- dozens of them per pixel stream, and 320 or 0.5 stayed unknowns it could
-- neither fold nor estimate with. Inlined, the settings fold into constants.
WITH RECURSIVE render_context AS NOT MATERIALIZED (
    SELECT {map_id} AS map_id,
           {thing_id} AS player_thing_id,
           -- Doom's 0..4 skill
           (SELECT mm.skill FROM mp_match mm LIMIT 1) AS skill,
           CASE WHEN (SELECT mm.skill FROM mp_match mm LIMIT 1)<=1 THEN 1 WHEN (SELECT mm.skill FROM mp_match mm LIMIT 1)=2 THEN 2 ELSE 4 END
             AS skill_bit
), pos AS MATERIALIZED (
    -- MATERIALIZED here (NOT MATERIALIZED in LBDoom): LBDoom's pose is
    -- parameters, ours a lookup in mp_players, which inlined ran ~8,000 times a
    -- frame (54 pages instead of 7,996), more as a live game's mp_players grows.
    -- The camera of the newest tic, read from player_state (since 2026-11-19):
    -- frames start on a tic commit and draw that tic, so the per-frame
    -- api_camera write to mp_players is not needed. The same arithmetic as
    -- api_camera at alpha 1, through real as the pose columns were, so the
    -- picture is byte-identical to what the api_camera(1.0) pose gave.
    SELECT (ps.previous_x + (ps.position_x - ps.previous_x) * 1.0::float8)::real::float8 AS x,
           (ps.previous_y + (ps.position_y - ps.previous_y) * 1.0::float8)::real::float8 AS y,
           (ps.previous_view_z + (ps.view_z - ps.previous_view_z) * 1.0::float8)::real::float8 AS z,
           (w.a0 + t.turn - 360.0 * FLOOR((w.a0 + t.turn) / 360.0))::real::float8 AS angle
    FROM mp_players mp
    JOIN player_state ps ON ps.map_id = mp.map_id AND ps.player_thing_id = mp.player_thing_id
    CROSS JOIN LATERAL (SELECT ps.previous_view_angle::float8 AS a0,
                               ps.view_angle::float8 - ps.previous_view_angle::float8 + 180.0 AS d) w
    CROSS JOIN LATERAL (SELECT (w.d - 360.0 * FLOOR(w.d / 360.0)) - 180.0 AS turn) t
    WHERE mp.map_id = {map_id} AND mp.slot = {slot} AND mp.role_name = doom_caller()
), me_state AS MATERIALIZED (
    -- The viewer's player_state row, read once (since 2026-11-19), for the
    -- clock, the weapon sprite and the status bar below. Read where it was
    -- used, its plan followed player_state's statistics: the referee's
    -- ANALYZE at a map change made a Nightmare E1M9 frame 55 -> 61 ms (bitmap
    -- scans on it, a nested loop in plane_span_info). MATERIALIZED and LIMIT
    -- 1: one row whatever the statistics say.
    SELECT ps.* FROM player_state ps
    WHERE ps.map_id = {map_id} AND ps.player_thing_id = {thing_id}
    LIMIT 1
), frame_clock AS (
    -- The gameplay clock, for the effects below that are pure functions of it.
    SELECT COALESCE(MAX(ps.level_tics), 0)::bigint AS t
    FROM me_state ps
), animated_light AS (
    -- Doom hangs a light thinker off every animated sector. Here the effect is
    -- a pure function of the tic count and the two endpoints resolved at level
    -- start into sector_light_fx, so it is evaluated for the frame being drawn.
    SELECT k.sector_id,
      LEAST(255::smallint, GREATEST(0::smallint,
    CASE k.special
      -- Strobes: 5 tics bright, then 15 (fast) or 35 (slow) dark.
      WHEN 2  THEN CASE WHEN ((k.t + k.phase) % 20) < 5 THEN k.base_light ELSE k.dark_light END
      WHEN 13 THEN CASE WHEN (k.t % 20) < 5 THEN k.base_light ELSE k.dark_light END
      WHEN 3  THEN CASE WHEN ((k.t + k.phase) % 40) < 5 THEN k.base_light ELSE k.dark_light END
      WHEN 12 THEN CASE WHEN (k.t % 40) < 5 THEN k.base_light ELSE k.dark_light END
      -- Irregular flicker
      WHEN 1  THEN CASE WHEN ((k.sector_id*2654435761 + (k.t / 4)) % 8) < 2
                        THEN k.dark_light ELSE k.base_light END
      -- Fire flicker
      WHEN 17 THEN GREATEST(k.dark_light,
                     k.base_light - ((((((k.t / 3) % 1000) * (((k.t / 3) % 1000))
                                        * 1103515245) + k.sector_id * 40503)
                                      % 1009) % 4
                       * GREATEST(1, (k.base_light - k.dark_light) / 4))::int)
      -- Glow
      WHEN 8  THEN (k.dark_light + 8 * (
                      CASE WHEN ((k.t + k.phase) % (2*k.glow_steps)) < k.glow_steps
                           THEN ((k.t + k.phase) % (2*k.glow_steps))
                           ELSE 2*k.glow_steps - ((k.t + k.phase) % (2*k.glow_steps))
                      END))
      ELSE k.base_light
    END
      ))::smallint AS light_level
    FROM (
      SELECT f.sector_id, f.base_light, f.dark_light, f.special,
             (f.sector_id*7919) % 64 AS phase,
             GREATEST(1, (f.base_light - f.dark_light) / 8) AS glow_steps,
             fc.t
      FROM sector_light_fx f
      CROSS JOIN render_context rc
      CROSS JOIN frame_clock fc
      WHERE f.map_id = rc.map_id
    ) k
), sectors_lit AS (
    -- sectors with the animated light applied
    SELECT s.map_id, s.id, s.floor_height, s.ceil_height,
           s.spawn_floor_height, s.spawn_ceil_height, s.spawn_floor_tex,
           s.spawn_light_level, s.floor_tex, s.ceil_tex,
           COALESCE(a.light_level, s.light_level) AS light_level,
           s.special, s.tag
    FROM sectors s
    CROSS JOIN render_context rc
    LEFT JOIN animated_light a ON a.sector_id = s.id
    WHERE s.map_id = rc.map_id
), scrolling_segs AS MATERIALIZED (
    -- MATERIALIZED: a few rows, hashed once, where inlined it was an index
    -- probe of linedefs per seg.
    -- Special 48 scrolls its wall one unit a tic
    SELECT ld.id AS linedef_id
    FROM linedefs ld CROSS JOIN render_context rc
    WHERE ld.map_id = rc.map_id AND ld.scrolls
), render_settings AS NOT MATERIALIZED (
    -- CedarDB resolves a select-list alias inside the same list (cx from
    -- screen_w, focal from fov_rad); Postgres does not, so the three base
    -- values come from a subquery and everything derived reads them from it.
    SELECT
      b.screen_w,
      b.screen_h,
      b.fov_rad,
      -- Every derived value is float8: a decimal literal is numeric in
      -- Postgres, and numeric arithmetic (software decimal) in the per-pixel
      -- stages costs several times what float8 does.
      (b.screen_w/2.0)::float8 AS cx,
      (b.screen_h/2.0)::float8 AS cy,
      ((b.screen_w/2.0)/tan(b.fov_rad/2.0))::float8 AS focal,
      tan(b.fov_rad/2.0)::float8   AS tan_half_fov,
      1e-3::float8 AS near,
      -- A flat is 64 world units across, so once one screen pixel steps more
      -- than a quarter of that the surface stops resembling its texture and
      -- turns to noise. The horizontal step of a plane is depth/focal, so this
      -- caps a plane's drawable depth.
      (16.0 * ((b.screen_w/2.0)/tan(b.fov_rad/2.0)))::float8 AS max_plane_depth,
      202.5::float8 AS rotation_offset,
      45.0::float8  AS rotation_span,
      32::int AS light_index_invuln,
      23::int AS light_psprite_bias,
      256.0::float8 AS sky_columns,
      90.0::float8  AS sky_degrees,
      128::int      AS sky_rows,
      100::int      AS sky_horizon_y,
      64::int AS flat_size
    FROM (SELECT 320::int AS screen_w,
                 168::int AS screen_h,  -- 200 minus the real 32px status bar
                 radians(90.0)::float8 AS fov_rad) b
), frame_walltex AS MATERIALIZED (
    -- The textures are stored compressed (TOAST), and GET_BYTE decompresses
    -- its whole argument on every call: per pixel, that was most of the
    -- frame. Concatenating with '' hands back a plain in-memory copy, and a
    -- MATERIALIZED CTE keeps it, so every pixel below reads that copy. Only
    -- the textures of the segs in view (heights, below) and the sky, about
    -- 20: all 30-60 of the map's took 2-3.5 ms a frame to decompress on
    -- Lakebase.
    SELECT m.name, m.width, m.height, (m.palette_indices || ''::bytea) AS palette_indices
    FROM walltex_meta m
    WHERE m.name IN (
      SELECT t.tex FROM heights_shown h
      CROSS JOIN LATERAL (VALUES (h.upper_tex), (h.mid_tex), (h.lower_tex)) t(tex)
      UNION
      SELECT ma.sky_texture FROM maps ma JOIN render_context rc ON rc.map_id = ma.map_id)
), frame_flats AS MATERIALIZED (
    -- The flats of this map's sectors, detoasted for the same reason.
    SELECT f.name, (f.palette_indices || ''::bytea) AS palette_indices
    FROM flat_textures f
    WHERE f.name IN (SELECT s.floor_tex FROM sectors_lit s
                     UNION SELECT s.ceil_tex FROM sectors_lit s)
), frame_sky AS MATERIALIZED (
    -- The map's sky texture from frame_walltex, with what the plane sampler
    -- asks of it: whether there is one (present), and whether it is whole --
    -- 256 columns of at least the 128 rows the sky draws.
    SELECT wt.palette_indices AS pi, wt.width,
           wt.palette_indices IS NOT NULL AS present,
           (wt.width >= rs.sky_columns::int
            AND OCTET_LENGTH(wt.palette_indices) >= wt.width * rs.sky_rows) AS whole
    FROM (SELECT m.sky_texture AS name FROM maps m JOIN render_context rc ON rc.map_id = m.map_id) sk
    CROSS JOIN render_settings rs
    LEFT JOIN frame_walltex wt ON wt.name = sk.name
), cam AS NOT MATERIALIZED (
    SELECT
    pos.x as px,
    pos.y as py,
    pos.z as pz,  -- eye height above floor
    -- Inlined, an expression here would be evaluated wherever it is used,
    -- per pixel; a scalar subquery is an InitPlan, evaluated once a frame.
    (SELECT radians(p.angle) FROM pos p) as view_rad,
    (SELECT COS(radians(p.angle)) FROM pos p) AS cos_v,
    (SELECT SIN(radians(p.angle)) FROM pos p) AS sin_v,
    (SELECT COS(-radians(p.angle)) FROM pos p) AS cos_nv,
    (SELECT SIN(-radians(p.angle)) FROM pos p) AS sin_nv
    FROM pos
), weapon_runtime AS (
    -- 'up'/'down' show the ready sprite while sx/sy slide.
    SELECT rc.map_id, rc.player_thing_id,
           COALESCE(w.sx, 1) AS sx, COALESCE(w.sy, 32) AS sy,
           -- The light amplification visor forces maximum brightness for
           -- its duration
           CASE WHEN COALESCE(ps2.light_amp_tics, 0) > 0 THEN 16
                ELSE COALESCE(w.flash_seq_index, -1) + 1 END AS extra_light,
           -- Invulnerability points Doom's fixedcolormap at COLORMAP row 32,
           -- the inverted one
           COALESCE(ps2.invuln_tics, 0) > 0 AS invuln,
           wd.sprite, wd.flash_sprite,
           CASE WHEN COALESCE(w.state, 'ready') IN ('up', 'down')
                THEN rf.frame ELSE mf.frame END AS frame,
           CASE WHEN COALESCE(w.state, 'ready') IN ('up', 'down')
                THEN rf.fullbright ELSE mf.fullbright END AS fullbright,
           ff.frame AS flash_frame, ff.fullbright AS flash_fullbright
    FROM render_context rc
    LEFT JOIN player_weapons w ON w.map_id = rc.map_id
      AND w.player_thing_id = rc.player_thing_id
    LEFT JOIN me_state ps2 ON ps2.map_id = rc.map_id
      AND ps2.player_thing_id = rc.player_thing_id
    JOIN weapon_defs wd ON wd.weapon_id = COALESCE(w.current_weapon, 2)
    LEFT JOIN weapon_frames rf ON rf.weapon_id = wd.weapon_id
      AND rf.state = 'ready' AND rf.seq_index = 0
    LEFT JOIN weapon_frames mf ON mf.weapon_id = wd.weapon_id
      AND mf.state = COALESCE(w.state, 'ready') AND mf.seq_index = COALESCE(w.seq_index, 0)
    LEFT JOIN weapon_frames ff ON ff.weapon_id = wd.weapon_id
      AND ff.state = 'flash' AND ff.seq_index = w.flash_seq_index
),
-- Conservative view-frustum test per node_children row. A child is skipped only when ALL FOUR of its
-- bbox corners lie strictly outside one of the 3 view half-planes (near clip, left FOV edge, right FOV edge).
-- MATERIALIZED: once per child (~500 rows) and a hash join, rather than
-- inlined into bsp_order as an index probe and a fresh test per path step
-- (~2,200).
visible_children AS MATERIALIZED (
  SELECT
    nc.map_id, nc.node_id, nc.side,
    -- Whether this child is the side of its node's splitter the camera is
    -- on: per node here, rather than per path step in bsp_order.
    nc.side = CASE
                WHEN (p.x - n.x)::bigint * n.dy::bigint - (p.y - n.y)::bigint * n.dx::bigint > 0
                  THEN 'R' ELSE 'L'
              END AS is_front,
    (c.px BETWEEN nc.bbox_left AND nc.bbox_right
     AND c.py BETWEEN nc.bbox_bottom AND nc.bbox_top)
    OR (
      -- MIN over the box of L = vy - vx*tan(halfFOV); keep unless proven
      -- fully outside the left edge.
      ((c.sin_nv - rs.tan_half_fov*c.cos_nv)
         * (CASE WHEN (c.sin_nv - rs.tan_half_fov*c.cos_nv) >= 0
                 THEN nc.bbox_left ELSE nc.bbox_right END)
       + (c.cos_nv + rs.tan_half_fov*c.sin_nv)
         * (CASE WHEN (c.cos_nv + rs.tan_half_fov*c.sin_nv) >= 0
                 THEN nc.bbox_bottom ELSE nc.bbox_top END)
       + (-c.px*c.sin_nv - c.py*c.cos_nv
          + rs.tan_half_fov*(c.px*c.cos_nv - c.py*c.sin_nv))
      ) <= 0.5
      AND
      -- MIN over the box of R = -vy - vx*tan(halfFOV); right edge.
      ((-c.sin_nv - rs.tan_half_fov*c.cos_nv)
         * (CASE WHEN (-c.sin_nv - rs.tan_half_fov*c.cos_nv) >= 0
                 THEN nc.bbox_left ELSE nc.bbox_right END)
       + (-c.cos_nv + rs.tan_half_fov*c.sin_nv)
         * (CASE WHEN (-c.cos_nv + rs.tan_half_fov*c.sin_nv) >= 0
                 THEN nc.bbox_bottom ELSE nc.bbox_top END)
       + (c.px*c.sin_nv + c.py*c.cos_nv
          + rs.tan_half_fov*(c.px*c.cos_nv - c.py*c.sin_nv))
      ) <= 0.5
      AND
      -- MIN over the box of N = near - vx; near clip plane.
      ((-c.cos_nv)
         * (CASE WHEN (-c.cos_nv) >= 0 THEN nc.bbox_left ELSE nc.bbox_right END)
       + (c.sin_nv)
         * (CASE WHEN c.sin_nv >= 0 THEN nc.bbox_bottom ELSE nc.bbox_top END)
       + (rs.near + c.px*c.cos_nv - c.py*c.sin_nv)
      ) <= 0.5
    ) AS keep
  FROM node_children nc
  JOIN nodes n ON n.map_id = nc.map_id AND n.id = nc.node_id
  CROSS JOIN pos p
  CROSS JOIN cam c
  CROSS JOIN render_settings rs
  CROSS JOIN render_context rctx
  WHERE nc.map_id = rctx.map_id
),
-- Front-to-back order over subsectors.
-- A nice property of Doom is that the BSP tree tells us exactly in which order we have
-- to render sectors without having to worry about overlaps - just start rendering at the first node
-- and continue filling pixels that haven't been set yet, until the bsp tree is fully traversed - divide and conquer!
-- We just have to traverse the bsp tree to our sector and record the front/back choices
-- along the way.
-- We cheat a little bit: SQL does set-oriented processing, which makes traversal expensive
-- and hard to express. So we just pre-compute all paths in node_path_steps.
-- And aggregate over that (~6k rows).
-- We then pack the choices we made into one bigint: back = 1 at bit (40 - depth), front = 0.
-- By sorting the keys lexicographically, we get an order in which to render segments.
-- We also apply pruning: A subsector under any culled child box is left out from further steps.
-- Sounds a little bit like cheating but even John Carmack himself set in 1993 that he is sure
-- there's going to be a future where rendering DOOM can just be brute-forced. Not sure if he
-- had SQL in mind, though.
node_fronts AS MATERIALIZED (
  -- The side of each node's splitter the camera is on: per node, rather
  -- than per path step in bsp_order.
  SELECT n.id AS node_id,
         CASE WHEN (p.x - n.x)::bigint * n.dy::bigint - (p.y - n.y)::bigint * n.dx::bigint > 0
              THEN 'R' ELSE 'L' END AS front
  FROM nodes n
  CROSS JOIN pos p
  CROSS JOIN render_context rc
  WHERE n.map_id = rc.map_id
),
visible_leaves AS MATERIALIZED (
  -- The subsectors visible_children's frustum test keeps: those whose path
  -- has no culled box. A child's box holds every box below it (true of
  -- every node of DOOM1.WAD's nine maps), and the test keeps a box whenever
  -- it keeps one inside it -- each of its minima over a box is at most the
  -- same minimum over a box inside -- so a subsector's own box decides for
  -- its whole path. One test a subsector (~200-470), not one a child of
  -- every node (~470-930). keep is a column, tested in bsp_order's join,
  -- where the planner estimates half of them kept: filtered here, it
  -- guessed a handful, and planned every stage after the walk for that.
  SELECT nc.child_ssector_id AS ssector_id,
         ((c.px BETWEEN nc.bbox_left AND nc.bbox_right
     AND c.py BETWEEN nc.bbox_bottom AND nc.bbox_top)
    OR (
      -- MIN over the box of L = vy - vx*tan(halfFOV); keep unless proven
      -- fully outside the left edge.
      ((c.sin_nv - rs.tan_half_fov*c.cos_nv)
         * (CASE WHEN (c.sin_nv - rs.tan_half_fov*c.cos_nv) >= 0
                 THEN nc.bbox_left ELSE nc.bbox_right END)
       + (c.cos_nv + rs.tan_half_fov*c.sin_nv)
         * (CASE WHEN (c.cos_nv + rs.tan_half_fov*c.sin_nv) >= 0
                 THEN nc.bbox_bottom ELSE nc.bbox_top END)
       + (-c.px*c.sin_nv - c.py*c.cos_nv
          + rs.tan_half_fov*(c.px*c.cos_nv - c.py*c.sin_nv))
      ) <= 0.5
      AND
      -- MIN over the box of R = -vy - vx*tan(halfFOV); right edge.
      ((-c.sin_nv - rs.tan_half_fov*c.cos_nv)
         * (CASE WHEN (-c.sin_nv - rs.tan_half_fov*c.cos_nv) >= 0
                 THEN nc.bbox_left ELSE nc.bbox_right END)
       + (-c.cos_nv + rs.tan_half_fov*c.sin_nv)
         * (CASE WHEN (-c.cos_nv + rs.tan_half_fov*c.sin_nv) >= 0
                 THEN nc.bbox_bottom ELSE nc.bbox_top END)
       + (c.px*c.sin_nv + c.py*c.cos_nv
          + rs.tan_half_fov*(c.px*c.cos_nv - c.py*c.sin_nv))
      ) <= 0.5
      AND
      -- MIN over the box of N = near - vx; near clip plane.
      ((-c.cos_nv)
         * (CASE WHEN (-c.cos_nv) >= 0 THEN nc.bbox_left ELSE nc.bbox_right END)
       + (c.sin_nv)
         * (CASE WHEN c.sin_nv >= 0 THEN nc.bbox_bottom ELSE nc.bbox_top END)
       + (rs.near + c.px*c.cos_nv - c.py*c.sin_nv)
      ) <= 0.5
    )) AS keep
  FROM node_children nc
  CROSS JOIN cam c
  CROSS JOIN render_settings rs
  CROSS JOIN render_context rctx
  WHERE nc.map_id = rctx.map_id AND nc.child_kind = 'SSECTOR'
),
bsp_order AS (
  SELECT s.ssector_id, ROW_NUMBER() OVER (ORDER BY s.sort_key) AS bsp_seq
  FROM (
    SELECT st.ssector_id,
           SUM(CASE WHEN st.side = nf.front THEN 0::bigint
                    ELSE (1::bigint << (40 - st.depth)) END) AS sort_key
    FROM node_path_steps st
    CROSS JOIN render_context rc
    -- only the visible subsectors' steps
    JOIN visible_leaves vl ON vl.ssector_id = st.ssector_id AND vl.keep
    JOIN node_fronts nf ON nf.node_id = st.node_id
    WHERE st.map_id = rc.map_id
    GROUP BY st.ssector_id
  ) s
),
player_sector AS (
  -- The first subsector in the front-to-back walk contains the camera.
  SELECT sec.*
  FROM bsp_order bo
  JOIN render_context rc ON TRUE
  JOIN render_segs sg ON sg.map_id = rc.map_id
    AND sg.ssector_id = bo.ssector_id
  JOIN sectors_lit sec ON sec.map_id = rc.map_id AND sec.id = sg.fsec
  WHERE bo.bsp_seq = 1
  ORDER BY sg.seg_id
  LIMIT 1
),
segs_with_verts AS (
  SELECT
    s.seg_id,
    s.direction,
    s.linedef_id,
    s.map_id,
    s.x1, s.y1, s.x2, s.y2,
    s.seg_u1, s.seg_u2,
    bo.bsp_seq                       -- which subsector, in walk order
  FROM render_segs s
  -- Only segs the BSP walk actually reached
  JOIN bsp_order bo ON bo.ssector_id = s.ssector_id
  CROSS JOIN pos
  CROSS JOIN render_context rc
  WHERE s.map_id = rc.map_id
    -- A Doom seg is directed so that its front sector lies on its right.
    -- Two-sided linedefs normally occur twice in SEGS, once per subsector and
    -- in opposite directions. Keep only the copy facing the camera.
    AND (s.x2 - s.x1)::bigint * (pos.y - s.y1)::bigint
      - (s.y2 - s.y1)::bigint * (pos.x - s.x1)::bigint < 0
),
viewspace AS (
    -- translate to camera origin and rotate by -view_rad in one step.
    SELECT
        s.seg_id,
        s.direction,
        s.linedef_id,
        s.map_id,
        s.seg_u1, s.seg_u2, s.bsp_seq,
        (s.x1 - c.px) * c.cos_nv - (s.y1 - c.py) * c.sin_nv AS x1,
        -((s.x1 - c.px) * c.sin_nv + (s.y1 - c.py) * c.cos_nv) AS y1,
        (s.x2 - c.px) * c.cos_nv - (s.y2 - c.py) * c.sin_nv AS x2,
        -((s.x2 - c.px) * c.sin_nv + (s.y2 - c.py) * c.cos_nv) AS y2
    FROM segs_with_verts s CROSS JOIN cam c
),
visible AS (
    SELECT * FROM viewspace WHERE x1 > 0 OR x2 > 0
),
clipped AS (
    SELECT
        seg_id,
        direction,
        linedef_id,
        map_id,
        seg_u1,
        seg_u2,
        bsp_seq,
        CASE WHEN x1 < near then near ELSE x1 END AS cx1,
        CASE WHEN x1 < near THEN y1 + (near - x1)*(y2 - y1)/(x2 - x1) ELSE y1 END AS cy1,
        CASE WHEN x2 < near then near ELSE x2 END AS cx2,
        CASE WHEN x2 < near THEN y2 + (near - x2)*(y1 - y2)/(x1 - x2) ELSE y2 END AS cy2
    FROM visible, render_settings
),
projected AS (
    SELECT
        seg_id,
        direction,
        linedef_id,
        map_id,
        cx1, cy1, cx2, cy2,
        cx + focal*(cy1/cx1) AS screen_x1,
        cx + focal*(cy2/cx2) AS screen_x2,
        1.0/cx1 AS invx1,
        1.0/cx2 AS invx2,
        seg_u1,
        seg_u2,
        bsp_seq
    FROM clipped, render_settings
),
on_screen AS (
  -- Frustum reject. A segment is retained when its clipped projected interval overlaps any part of the screen.
  -- this also keeps segments whose two endpoints lie outside opposite edges (ask me how I found this out the hard way).
  SELECT p.*
  FROM projected p
  CROSS JOIN render_settings rs
  WHERE GREATEST(p.screen_x1, p.screen_x2) >= 0
    AND LEAST(p.screen_x1, p.screen_x2) < rs.screen_w
),
heights AS (
  SELECT
    p.*, s.fsec, s.bsec,
    (s.x_offset + CASE WHEN sc.linedef_id IS NULL THEN 0 ELSE fc.t END) AS x_offset,
    s.y_offset,
    s.upper_tex, s.mid_tex, s.lower_tex, s.flags,
    s.f_floor, s.f_ceil, s.f_ceil_tex,
    -- f_light/b_light are the sector's static light, an animated sector's value is computed above
    COALESCE(alf.light_level, s.f_light) AS f_light,
    s.b_floor, s.b_ceil, s.b_ceil_tex,
    COALESCE(alb.light_level, s.b_light) AS b_light,
    -- Doom gives horizontal walls one darker light step and vertical
    -- walls one brighter step, so edges/corners are easier to see
    s.light_bias
  FROM on_screen p
  -- (CedarDB needed `s.seg_id + 0` here to pick its join order; in Postgres
  -- that expression hides the primary key and every seg scanned the map.)
  JOIN render_segs s ON s.map_id = p.map_id AND s.seg_id = p.seg_id
  CROSS JOIN frame_clock fc
  LEFT JOIN animated_light alf ON alf.sector_id = s.fsec
  LEFT JOIN animated_light alb ON alb.sector_id = s.bsec
  LEFT JOIN scrolling_segs sc ON sc.linedef_id = s.linedef_id
),
occluders AS (
  -- segs that fully block anything farther
  -- one-sided walls, or two-sided walls whose back sector is degenerate
  -- (closed door / dummy sector)
  SELECT h.seg_id, h.screen_x1, h.screen_x2, h.bsp_seq
  FROM heights h
  WHERE h.bsec IS NULL OR h.b_ceil <= h.b_floor
),
occlusion_cols AS (
  SELECT generate_series((GREATEST(0, FLOOR(LEAST(o.screen_x1, o.screen_x2))::int)) + ((GREATEST(0, FLOOR(LEAST(o.screen_x1, o.screen_x2))::int)) & 1), LEAST(rs.screen_w - 1, CEIL(GREATEST(o.screen_x1, o.screen_x2))::int), 2) AS col_x,
         o.bsp_seq
  FROM occluders o
  CROSS JOIN render_settings rs
  WHERE o.screen_x1 <> o.screen_x2
),
min_occlusion AS (
  -- nearest (smallest bsp_seq) fully-solid occluder covering each column;
  -- anything with a strictly larger bsp_seq in that column is behind it and
  -- can be ignored
  SELECT col_x, MIN(bsp_seq) AS min_bsp_seq
  FROM occlusion_cols
  GROUP BY col_x
),
occlusion_arr AS MATERIALIZED (
  -- min_occlusion as an array by column (index x + 1), the largest bigint
  -- where nothing occludes: one subscript per column instead of a join.
  SELECT array_agg(COALESCE(mo.min_bsp_seq, 9223372036854775807) ORDER BY g.x) AS a
  FROM render_settings rs
  CROSS JOIN LATERAL generate_series(0, rs.screen_w - 1) AS g(x)
  LEFT JOIN min_occlusion mo ON mo.col_x = g.x
),
heights_shown AS (
  -- The segs not wholly behind a nearer occluder: those with a column that
  -- columns keeps. Most of a busy view's segs are hidden (up to 95% of the
  -- columns they would make), and their parts and columns are not made.
  SELECT h.*
  FROM heights h
  CROSS JOIN occlusion_arr oa
  CROSS JOIN render_settings rs
  WHERE NOT (h.bsp_seq > ALL (oa.a[GREATEST(0, FLOOR(LEAST(h.screen_x1, h.screen_x2))::int) + 1
                                 : LEAST(rs.screen_w - 1, CEIL(GREATEST(h.screen_x1, h.screen_x2))::int) + 1]))
),
wall_parts AS (
  -- SOLID (one-sided)
  SELECT seg_id, 'solid' AS part, mid_tex AS tex, x_offset, y_offset, flags,
         f_floor AS z_bot, f_ceil AS z_top,
         CASE WHEN (flags & 16)<>0 THEN f_floor ELSE f_ceil END AS v_anchor_base,
         (flags & 16)<>0 AS v_anchor_add_tex_h,
         f_light, fsec, invx1, invx2, screen_x1, screen_x2, cx1, cx2, cy1, cy2, seg_u1, seg_u2,
         bsp_seq, light_bias
  FROM heights_shown
  WHERE bsec IS NULL
  AND f_ceil > f_floor            -- skip zero/inverted-height (dummy) sectors

  UNION ALL
  -- UPPER (two-sided, when back ceiling < front ceiling)
  SELECT seg_id, 'upper', upper_tex, x_offset, y_offset, flags,
         b_ceil AS z_bot, f_ceil AS z_top,
         CASE WHEN (flags & 8)<>0 THEN f_ceil ELSE b_ceil END AS v_anchor_base,
         (flags & 8)=0 AS v_anchor_add_tex_h,
         f_light, fsec, invx1, invx2, screen_x1, screen_x2, cx1, cx2, cy1, cy2, seg_u1, seg_u2,
         bsp_seq, light_bias
  FROM heights_shown
  WHERE bsec IS NOT NULL
  AND b_ceil < f_ceil
  -- Doom joins adjacent sky ceilings visually even when their numeric heights
  -- differ. Drawing this upper wall creates a fake floating overhang whose
  -- "underside" is (correctly) still sky.
  AND (f_ceil_tex IS DISTINCT FROM 'F_SKY1'
       OR b_ceil_tex IS DISTINCT FROM 'F_SKY1')

  UNION ALL
  -- CEILING OPEN-UP (two-sided, back ceiling at or above the front ceiling).
  -- There is no wall surface on the camera-facing side, but the front ceiling
  -- ends at this portal. Keep it as a clip-only boundary.
  SELECT seg_id, 'upper_open', NULL::text, x_offset, y_offset, flags,
         f_ceil AS z_bot, b_ceil AS z_top,
         b_ceil AS v_anchor_base,FALSE AS v_anchor_add_tex_h,
         f_light, fsec, invx1, invx2, screen_x1, screen_x2, cx1, cx2, cy1, cy2, seg_u1, seg_u2,
         bsp_seq, light_bias
  FROM heights_shown
  WHERE bsec IS NOT NULL
  AND b_ceil > f_ceil
  AND (f_ceil_tex IS DISTINCT FROM 'F_SKY1'
       OR b_ceil_tex IS DISTINCT FROM 'F_SKY1')

  UNION ALL
  -- CEILING FLUSH BOUNDARY (two-sided, both ceilings at the same height).
  -- Draws no wall, but unlike upper_open it DOES close the near ceiling:
  -- beyond this line the ceiling belongs to the back sector.
  SELECT seg_id, 'upper_flush', NULL::text, x_offset, y_offset, flags,
         f_ceil AS z_bot, b_ceil AS z_top,
         b_ceil AS v_anchor_base,FALSE AS v_anchor_add_tex_h,
         f_light, fsec, invx1, invx2, screen_x1, screen_x2, cx1, cx2, cy1, cy2, seg_u1, seg_u2,
         bsp_seq, light_bias
  FROM heights_shown
  WHERE bsec IS NOT NULL
  AND b_ceil = f_ceil
  AND (f_ceil_tex IS DISTINCT FROM 'F_SKY1'
       OR b_ceil_tex IS DISTINCT FROM 'F_SKY1')

  UNION ALL
  -- LOWER step-up (two-sided, back floor higher than front floor)
  SELECT seg_id, 'lower', lower_tex, x_offset, y_offset, flags,
         f_floor AS z_bot, b_floor AS z_top,
         CASE WHEN (flags & 16)<>0 THEN f_ceil ELSE b_floor END AS v_anchor_base,
         FALSE AS v_anchor_add_tex_h,
         f_light, fsec, invx1, invx2, screen_x1, screen_x2, cx1, cx2, cy1, cy2, seg_u1, seg_u2,
         bsp_seq, light_bias
  FROM heights_shown
  WHERE bsec IS NOT NULL
  AND b_floor > f_floor

  UNION ALL
  -- FLOOR OPEN-DOWN (two-sided, back floor at or below the front floor). The
  -- riser faces the opposite side, so this camera-facing copy is clip-only.
  SELECT seg_id, 'lower_down', NULL::text, x_offset, y_offset, flags,
         b_floor AS z_bot, f_floor AS z_top,
         f_floor AS v_anchor_base,FALSE AS v_anchor_add_tex_h,
         f_light, fsec, invx1, invx2, screen_x1, screen_x2, cx1, cx2, cy1, cy2, seg_u1, seg_u2,
         bsp_seq, light_bias
  FROM heights_shown
  WHERE bsec IS NOT NULL
  AND b_floor <= f_floor

  UNION ALL
  -- MID MASKED (two-sided decorative; draws over the opening)
  SELECT seg_id, 'midmask', mid_tex, x_offset, y_offset, flags,
         /* pegging will decide exact vertical placement; provisional full height */
         f_floor AS z_bot, f_ceil AS z_top,
         CASE WHEN (flags & 16)<>0 THEN GREATEST(f_floor,b_floor)
              ELSE LEAST(f_ceil,b_ceil) END AS v_anchor_base,
         (flags & 16)<>0 AS v_anchor_add_tex_h,
         f_light, fsec, invx1, invx2, screen_x1, screen_x2, cx1, cx2, cy1, cy2, seg_u1, seg_u2,
         bsp_seq, light_bias
  FROM heights_shown
  WHERE bsec IS NOT NULL
  AND mid_tex IS NOT NULL
  AND mid_tex <> '-' -- TODO
  AND f_ceil > f_floor            -- skip zero/inverted-height (dummy) sectors
),
wall_parts_tex AS (
  -- The texture is a property of the seg part, so its size is looked up here,
  -- once per visible seg part (a few hundred rows). Its bytes are not: they
  -- would ride along into `vertical`, which is materialized, and a
  -- materialized row holds its own copy of every value -- a whole texture per
  -- screen column, ~15 MB a frame written to temp files. clamped_spans_lit
  -- fetches them per span instead.
  SELECT wp.*,
         COALESCE(m.width, 64)  AS tex_w,
         COALESCE(m.height, 64) AS tex_h,
         m.width                AS tex_width
  FROM wall_parts wp
  LEFT JOIN walltex_meta m ON m.name = wp.tex
),
columns AS (
  SELECT
    w.*,
    (w.x_offset + w.seg_u1) AS u1,   -- wall U at the two endpoints
    (w.x_offset + w.seg_u2) AS u2,
    w.x AS col_x,
    w.x AS screen_x_clamped,         -- already clamped by bounds below
    -- clamp t to [0,1]: the generate_series range is FLOOR/CEIL of the
    -- projected span, which can extend one column past each endpoint at
    -- T-junctions. Without clamping, t leaves [0,1] and extrapolates the
    -- wall across the crack, producing 1px vertical strips of the wrong wall.
    LEAST(1.0, GREATEST(0.0,
      (w.x - w.screen_x1) / NULLIF(w.screen_x2 - w.screen_x1, 1e-6))) AS t
  FROM (
    -- one row per screen column of a seg part, from a select-list
    -- generate_series (see fragments)
    SELECT w.*, generate_series((b.x_lo) + ((b.x_lo) & 1), b.x_hi, 2) AS x
    FROM wall_parts_tex w
    CROSS JOIN render_settings rs
    CROSS JOIN LATERAL (
      SELECT
        -- quick reject if the entire projected span is off-screen
        NOT (GREATEST(w.screen_x1, w.screen_x2) < 0 OR LEAST(w.screen_x1, w.screen_x2) >= rs.screen_w) AS on_screen,
        GREATEST(0, FLOOR(LEAST(w.screen_x1, w.screen_x2))::int)    AS x_lo,
        LEAST  (rs.screen_w-1, CEIL (GREATEST(w.screen_x1, w.screen_x2))::int) AS x_hi
    ) b
    WHERE b.on_screen
      AND w.screen_x1 <> w.screen_x2
  ) w
  CROSS JOIN occlusion_arr oa
  -- occlusion: skip columns where a nearer (smaller bsp_seq) fully-solid
  -- wall has already closed off anything farther
  WHERE w.bsp_seq <= oa.a[w.x + 1]
  -- A subquery of its own, so t is computed once per column: inlined into
  -- per_column and vertical it would be re-evaluated at each of its seven
  -- uses (through invx, u_over_x, depth_x, u_col and scale).
  OFFSET 0
),
per_column AS (
  SELECT
    c.*,
    iv.invx,
    iv.u_over_x,
    1.0 / iv.invx                       AS depth_x,
    iv.u_over_x / NULLIF(iv.invx, 1e-6) AS u_col,
    -- scale factor at this column
    rs.focal * iv.invx                  AS scale
  FROM columns c
  CROSS JOIN render_settings rs
  CROSS JOIN LATERAL (
    SELECT
      -- inverse depth and perspective-correct U, interpolated per column
      c.invx1 + c.t * (c.invx2 - c.invx1)                       AS invx,
      (c.u1 * c.invx1) + c.t * ((c.u2 * c.invx2) - (c.u1 * c.invx1)) AS u_over_x
  ) iv
),
vertical AS (
  -- Materialized (clamped_spans and panel_cols both read it), and a
  -- materialized CTE computes and stores every column it has: so only the
  -- ones those two read, not the ~45 the stages above it carry.
  SELECT
    p.seg_id, p.part, p.tex, p.y_offset, p.f_light,
    p.tex_w, p.tex_h, p.tex_width, p.bsp_seq, p.light_bias,
    p.col_x, p.screen_x_clamped, p.depth_x, p.u_col, p.scale,
    c.pz AS view_z,rs.cy AS screen_cy,
    (rs.cy - p.scale * (p.z_top - c.pz)) AS y_top_f,
    (rs.cy - p.scale * (p.z_bot - c.pz)) AS y_bot_f,
    -- tex_w / tex_h (texture size, 64x64 if missing) come with the seg part
    p.v_anchor_base
      + CASE WHEN p.v_anchor_add_tex_h THEN p.tex_h ELSE 0 END
      AS v_anchor_z
  FROM per_column p
  CROSS JOIN render_settings rs
  CROSS JOIN cam c
),
clamped_spans AS (
  SELECT
    t.*,
    -- Doom samples wall V in world units. Inverting the perspective
    -- projection gives world_z at the first visible pixel; advancing one
    -- screen row changes V by 1/scale.
    t.v_anchor_z
      - (t.view_z+(t.screen_cy-t.y_start::float8)/NULLIF(t.scale,1e-9))
      + t.y_offset::float8 AS v0,
    1.0/NULLIF(t.scale,1e-9) AS v_step
  FROM (
    SELECT
      v.*,
      -- clamp to [0 .. screen_h-1] in FLOAT, then cast
      CEIL (
        LEAST( rs.screen_h - 1.0::float8,
               GREATEST(0.0::float8, LEAST(v.y_top_f, v.y_bot_f))
        )
      )::int AS y_start,
      FLOOR(
        LEAST( rs.screen_h - 1.0::float8,
               GREATEST(0.0::float8, GREATEST(v.y_top_f, v.y_bot_f))
        )
      )::int AS y_end
    FROM vertical v
    CROSS JOIN render_settings rs
    -- keep only spans that intersect the screen vertically
    WHERE LEAST(v.y_top_f, v.y_bot_f) < rs.screen_h
      AND GREATEST(v.y_top_f, v.y_bot_f) >= 0
  ) t
  -- final guard: ignore empty/inverted spans
  WHERE t.y_end >= t.y_start
),
clamped_spans_lit AS (
  SELECT c.*, cu.u_i, wt.palette_indices AS tex_pi,
         -- The texel offset below can only leave the texture through U (V is
         -- an integer modulo of tex_h): when this column's U is inside and
         -- the texture is whole, every pixel of the span reads in range.
         (wt.palette_indices IS NOT NULL AND cu.u_i >= 0 AND cu.u_i < c.tex_width
          AND OCTET_LENGTH(wt.palette_indices) >= c.tex_width * c.tex_h) AS texel_safe,
         CASE WHEN wr.invuln THEN rs.light_index_invuln
              ELSE doom_light_index(c.f_light, c.light_bias + wr.extra_light,
                                    doom_light_scale(c.depth_x))
         END AS light_index,
         (c.seg_id::bigint*8 + CASE c.part
            WHEN 'solid' THEN 0 WHEN 'upper' THEN 1 WHEN 'lower' THEN 2
            WHEN 'lower_down' THEN 3 ELSE 7 END)::bigint AS stable_id
  FROM clamped_spans c
  CROSS JOIN LATERAL (
    -- integerized, positive-modulo U: one texture column per screen column
    SELECT (FLOOR(c.u_col - c.tex_w * FLOOR(c.u_col / c.tex_w))::int) AS u_i
  ) cu
  LEFT JOIN frame_walltex wt ON wt.name = c.tex
  CROSS JOIN weapon_runtime wr
  CROSS JOIN render_settings rs
),
wall_spans AS (
  -- The depth-resolve key (see view_lanes) of a wall pixel is the same
  -- all the way down its span except for the texel in the low byte, so all
  -- of it but the texel is computed here, once per span (~900 rows) instead
  -- of once per pixel (~35k). OR-ing the texel in per pixel gives the same
  -- bits.
  --
  -- OFFSET 0 is what makes "once per span" true. Inlined into the pixel
  -- query, every expression of this CTE and of the ones it reads
  -- (clamped_spans_lit, clamped_spans, ...) would be evaluated where it is
  -- used: per pixel, because the select-list generate_series below
  -- re-evaluates its whole select list for every row it emits. As a subquery
  -- of its own, a span is computed once and its pixels read the result.
  SELECT c.*,
         ((GREATEST(0.0::float8, LEAST(c.depth_x, 131071.0))*4096)::bigint << 34)
         | ((2::bigint - 2::bigint) << 32)
         | (LEAST(0::bigint, 3::bigint) << 30)
         | (LEAST(65535::bigint, GREATEST(0::bigint, c.stable_id + 32768)) << 14)
         | (c.light_index::bigint << 8) AS key_hi
  FROM clamped_spans_lit c
  WHERE c.tex IS NOT NULL AND c.tex <> '-'
  OFFSET 0
),
wall_lanes AS (
  -- Sixteen wall pixels a row: lanes k0..k15 are screen rows 16g..16g+15 of
  -- the span's column, each the pixel's resolve key (see view_lanes), or
  -- NULL where the span does not reach. A row costs several times what the
  -- arithmetic of a pixel does (~110 ns on Lakebase against ~20), so many
  -- pixels to a row is most of what made the pixel stages cheap (eight were
  -- 30% off the frame, sixteen 2 ms more, thirty-two 1 ms worse again); the
  -- lanes' keys are resolved by MIN per lane (view_words) instead of
  -- sorted. The
  -- rows come from generate_series in a select list (ProjectSet), which
  -- streams them; the span brings only the columns read here, because the
  -- ProjectSet copies every column it has into each row it emits. The lanes
  -- are identical but for their row (tools/gen_lanes.py prints them).
  SELECT w.screen_x_clamped AS x, w.g,
    CASE WHEN (w.g*16+0) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+0) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+0) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+0) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+0) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k0,
    CASE WHEN (w.g*16+1) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+1) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+1) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+1) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+1) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k1,
    CASE WHEN (w.g*16+2) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+2) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+2) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+2) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+2) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k2,
    CASE WHEN (w.g*16+3) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+3) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+3) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+3) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+3) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k3,
    CASE WHEN (w.g*16+4) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+4) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+4) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+4) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+4) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k4,
    CASE WHEN (w.g*16+5) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+5) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+5) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+5) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+5) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k5,
    CASE WHEN (w.g*16+6) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+6) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+6) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+6) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+6) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k6,
    CASE WHEN (w.g*16+7) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+7) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+7) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+7) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+7) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k7,
    CASE WHEN (w.g*16+8) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+8) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+8) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+8) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+8) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k8,
    CASE WHEN (w.g*16+9) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+9) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+9) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+9) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+9) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k9,
    CASE WHEN (w.g*16+10) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+10) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+10) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+10) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+10) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k10,
    CASE WHEN (w.g*16+11) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+11) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+11) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+11) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+11) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k11,
    CASE WHEN (w.g*16+12) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+12) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+12) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+12) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+12) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k12,
    CASE WHEN (w.g*16+13) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+13) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+13) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+13) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+13) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k13,
    CASE WHEN (w.g*16+14) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+14) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+14) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+14) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+14) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k14,
    CASE WHEN (w.g*16+15) BETWEEN w.y_start AND w.y_end THEN w.key_hi | (CASE
      WHEN w.texel_safe THEN GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+15) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i))
      WHEN w.tex_pi IS NULL OR (((FLOOR(w.v0 + ((w.g*16+15) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) < 0 OR (((FLOOR(w.v0 + ((w.g*16+15) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i) >= OCTET_LENGTH(w.tex_pi) THEN 0
      ELSE GET_BYTE(w.tex_pi, (((FLOOR(w.v0 + ((w.g*16+15) - w.y_start)*w.v_step)::int % w.tex_h + w.tex_h) % w.tex_h) * w.tex_width + w.u_i)) END)::bigint END AS k15
  FROM (SELECT ws.screen_x_clamped, ws.key_hi, ws.texel_safe, ws.tex_pi, ws.tex_width,
               ws.tex_h, ws.u_i, ws.v0, ws.v_step, ws.y_start, ws.y_end,
               generate_series(ws.y_start >> 4, ws.y_end >> 4) AS g
        FROM wall_spans ws) w
),

-- VISPLANES!
-- You thought it was complicated before? This is where the fun starts!
-- Visplanes are a very elegant concept in a 2.5D game that is written in an
-- imperative language like C.
-- They are absolut hell in SQL.
--
-- Walls are correctly rendered now. We're missing floors and ceilings:
-- Everything that is not a wall is either a floor or a ceiling (called visplane in Doom).
-- This is a pretty ingenous hack to get 3D-y looking frames without having to
-- think about perspective - Doom just uses a pretty simple and fast floodfill algorithm.
--
-- We have to be more careful here and abuse window functions:
-- We go front-to-back per column. We maintain one open band [cc, fc] (ceiling-clip,
-- floor-clip) per column.
-- Each wall panel is either top-anchored (solid/upper: pushes cc down to its y_bot)
-- or bottom-anchored (solid/lower: pushes fc up to its y_top).
-- The pixel NOT covered by a wall, but inside the current open band,
-- is filled with the FRONT sector's ceiling (above) or floor (below). Through a
-- two-sided portal the upper+lower walls shrink the band from both sides.
-- Farther walls then fill that opening with the back sector's planes.
panel_cols AS (
  -- Drawable walls only matter when their vertical span intersects the screen.
  -- Unfortunately, we also have to look at portals completely off-screen:
  -- their projected front plane can still bound a visible floor or ceiling.
  SELECT
    v.col_x,
    v.seg_id,
    v.bsp_seq,
    v.part,
    -- The part's place in text order, which the panels are ordered by: an
    -- integer compares for less than a string does.
    CASE v.part WHEN 'lower' THEN 0 WHEN 'lower_down' THEN 1 WHEN 'midmask' THEN 2
                WHEN 'solid' THEN 3 WHEN 'upper' THEN 4 WHEN 'upper_flush' THEN 5
                ELSE 6 END AS part_ord,
    v.depth_x,
    v.y_top_f,
    v.y_bot_f,
    -- Screen rows where this seg's front planes meet the boundary.
    CASE WHEN v.part = 'lower_down' THEN v.y_top_f ELSE v.y_bot_f END AS f_floor_y_f,
    CASE WHEN v.part = 'upper_open' THEN v.y_bot_f ELSE v.y_top_f END AS f_ceil_y_f,
    h.fsec,
    h.f_light,
    h.f_floor,
    h.f_ceil,
    (h.f_ceil_tex = 'F_SKY1') AS f_ceil_is_sky
  FROM vertical v
  JOIN heights_shown h ON h.seg_id = v.seg_id
  CROSS JOIN render_settings rs
  WHERE v.part IN ('upper_open','upper_flush','lower_down')
     OR (LEAST(v.y_top_f, v.y_bot_f) < rs.screen_h
         AND GREATEST(v.y_top_f, v.y_bot_f) >= 0)
),
panel_seq AS (
  -- The front-to-back position of each panel within its column
  SELECT p.*,
         ROW_NUMBER() OVER (
           PARTITION BY p.col_x
           ORDER BY p.depth_x ASC, p.bsp_seq ASC, p.part_ord, p.seg_id
         ) AS seq
  FROM panel_cols p
),
panel_clips AS (
  -- The panel carried into each panel is the nearest earlier one in its
  -- column whose ceiling is above (floor below) the eye. CedarDB ran that as
  -- two LATERAL lookups; Postgres re-scans the whole CTE for each of them.
  -- Here the running MAX that finds the carried panel carries its fields
  -- too: each value packs the panel's seq above the fields it carries, so
  -- the largest is the latest qualifying panel and its low bits are that
  -- panel's fields. That replaces two self-joins of panel_seq. A field packs
  -- as value + 2^31 (int) or + 2^15 (smallint), with a flag bit for NULL, so
  -- the decoded value is exactly the panel's own.
  SELECT
    p.*,
    CASE WHEN p.ceil_k IS NULL OR (p.ceil_k >> 50) & 1 = 1 THEN NULL
         ELSE ((p.ceil_k >> 34) & 65535)::int END AS carried_ceil_sec,
    CASE WHEN p.ceil_k IS NULL OR (p.ceil_k >> 33) & 1 = 1 THEN NULL
         ELSE (((p.ceil_k >> 17) & 65535) - 32768)::smallint END AS carried_ceil_z,
    CASE WHEN p.ceil_k IS NULL OR (p.ceil_k >> 16) & 1 = 1 THEN NULL
         ELSE ((p.ceil_k & 65535) - 32768)::smallint END AS carried_ceil_light,
    COALESCE((p.ceil_k >> 51) & 1 = 1, FALSE) AS carried_ceil_is_sky,
    CASE WHEN p.floor_k IS NULL OR (p.floor_k >> 50) & 1 = 1 THEN NULL
         ELSE ((p.floor_k >> 34) & 65535)::int END AS carried_floor_sec,
    CASE WHEN p.floor_k IS NULL OR (p.floor_k >> 33) & 1 = 1 THEN NULL
         ELSE (((p.floor_k >> 17) & 65535) - 32768)::smallint END AS carried_floor_z,
    CASE WHEN p.floor_k IS NULL OR (p.floor_k >> 16) & 1 = 1 THEN NULL
         ELSE ((p.floor_k & 65535) - 32768)::smallint END AS carried_floor_light
  FROM (
    SELECT
      p.*,
      COALESCE(
        MAX(CASE
              WHEN part IN ('solid','upper')
                THEN FLOOR(LEAST(rs.screen_h - 1.0, GREATEST(0.0, y_bot_f)))::int + 1
              -- A flush boundary draws no wall.
              WHEN part = 'upper_flush'
                THEN GREATEST(0, FLOOR(LEAST(rs.screen_h - 1.0, y_bot_f))::int + 1)
              -- An opening up ends the near ceiling at its own top edge (its
              -- ceiling span's last row is the CEIL below less one).
              WHEN part = 'upper_open' AND NOT f_ceil_is_sky AND f_ceil > c.pz
                THEN CEIL(LEAST(rs.screen_h - 1.0, GREATEST(0.0, y_bot_f)))::int
            END)
          OVER w_before,
        0
      ) AS cc_before,
      -- A lower wall raises floorclip to the top of the riser (the bottom of the
      -- portal opening). A solid wall closes it in the same direction.
      COALESCE(
        MIN(CASE WHEN part IN ('solid','lower','lower_down')
                 THEN LEAST(rs.screen_h - 1, CEIL(GREATEST(0.0, y_top_f))::int - 1) END)
          OVER w_before,
        rs.screen_h - 1
      ) AS fc_before,
      -- Doom starts a ceiling visplane only for a ceiling that is higher then the viewer.
      -- We need to continue drawing the ceiling that is already in porgress until we hit a wall.
      -- So let's carry it here: seq | sector, and seq | sky | height | light.
      -- seq (11 bits, from bit 52) | sky (51) | sector (34-49, NULL flag
      -- 50) | height + 32768 (17-32, flag 33) | light + 32768 (0-15, flag 16):
      -- one MAX for the carried panel's fields, where the sector and the rest
      -- took two. A sector id fits 16 bits (a WAD indexes them so), a
      -- height and a light are smallints; a column holds far fewer than the
      -- 2048 panels seq has room for.
      MAX(CASE WHEN p.f_ceil > c.pz THEN
            (p.seq << 52)
            | (CASE WHEN p.f_ceil_is_sky THEN 1::bigint ELSE 0::bigint END << 51)
            | (CASE WHEN p.fsec IS NULL THEN 65536 ELSE p.fsec::bigint END << 34)
            | (CASE WHEN p.f_ceil IS NULL THEN 65536 ELSE p.f_ceil::bigint + 32768 END << 17)
            | CASE WHEN p.f_light IS NULL THEN 65536 ELSE p.f_light::bigint + 32768 END
          END) OVER w_before AS ceil_k,
      MAX(CASE WHEN p.f_floor < c.pz THEN
            (p.seq << 52)
            | (CASE WHEN p.fsec IS NULL THEN 65536 ELSE p.fsec::bigint END << 34)
            | (CASE WHEN p.f_floor IS NULL THEN 65536 ELSE p.f_floor::bigint + 32768 END << 17)
            | CASE WHEN p.f_light IS NULL THEN 65536 ELSE p.f_light::bigint + 32768 END
          END) OVER w_before AS floor_k
    FROM panel_seq p
    CROSS JOIN render_settings rs
    CROSS JOIN cam c
    -- panel_seq's own order, so seq and these share one sort: seq numbers
    -- the panels in exactly this order.
    WINDOW w_before AS (PARTITION BY p.col_x
                        ORDER BY p.depth_x ASC, p.bsp_seq ASC, p.part_ord, p.seg_id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING)
  ) p
),
nearest_panels AS MATERIALIZED (
  -- The nearest floor and ceiling bounds of each column, for the seeds
  -- below, in one pass over the panels. An upper wall changes only the
  -- ceiling and must not truncate the near floor: bound it with the first
  -- solid/lower transition in each column. Conversely, lower walls do not
  -- affect the ceiling: bound the near ceiling with the first solid/upper
  -- transition. NULL where a column has none.
  SELECT col_x,
         MIN(depth_x) FILTER (WHERE part IN ('solid','lower','lower_down')) AS floor_depth,
         MIN(depth_x) FILTER (WHERE part IN ('solid','upper','upper_open','upper_flush')) AS ceil_depth
  FROM panel_cols
  GROUP BY col_x
),
plane_spans_raw AS (
  -- Ceiling fill up to the projected FRONT ceiling. upper_open is clip-only:
  -- it ends the near ceiling without drawing a wall or tightening cc.
  SELECT
    k.col_x,
    CASE WHEN k.f_ceil > c.pz OR k.f_ceil_is_sky
         THEN k.fsec    ELSE k.carried_ceil_sec   END AS sector_id,
    CASE WHEN k.f_ceil > c.pz OR k.f_ceil_is_sky
         THEN k.f_ceil  ELSE k.carried_ceil_z     END AS plane_z,
    CASE WHEN k.f_ceil > c.pz OR k.f_ceil_is_sky
         THEN k.f_light ELSE k.carried_ceil_light END AS sector_light,
    CASE WHEN k.f_ceil > c.pz OR k.f_ceil_is_sky
         THEN k.f_ceil_is_sky ELSE k.carried_ceil_is_sky END AS is_sky,
    'ceil'::text AS plane, 1::int AS source_priority,
    GREATEST(0, k.cc_before) AS y0,
    b.y1
  FROM panel_clips k
  CROSS JOIN render_settings rs
  CROSS JOIN cam c
  CROSS JOIN LATERAL (
    SELECT CEIL(LEAST(rs.screen_h - 1.0, GREATEST(0.0,
      CASE
        -- The panel's own ceiling is bounded by the panel's own top edge.
        WHEN k.f_ceil > c.pz OR k.f_ceil_is_sky THEN k.f_ceil_y_f
        -- A carried ceiling has no wall of its own to end it, so it would run
        -- to the horizon and be sampled at thousands of map units per pixel.
        -- Stop it where sampling would alias.
        ELSE LEAST(k.f_ceil_y_f,
                   rs.cy - rs.focal * (k.carried_ceil_z - c.pz)
                           / rs.max_plane_depth)
      END
    )))::int - 1 AS y1
  ) b
  WHERE k.part IN ('solid','upper','upper_open','upper_flush','midmask')
    AND b.y1 >= k.cc_before
    -- Sky is unbounded, so Doom fills any ceiling region that is not otherwise filled.
    AND (k.f_ceil > c.pz OR k.f_ceil_is_sky
         OR k.carried_ceil_is_sky OR k.cc_before > 0)
  UNION ALL
  -- A wall triggers a floor for it's "FRONT" sector. Starting from its floor boundary
  -- down to the floor clip established by nearer walls.
  -- This rule handles solid walls, step-up and step-down portals.
  -- We don't have to care abou the "BACK" sector, as farther, camera-facing
  -- sector sides should fill that later on.
  SELECT
    k.col_x,
    CASE WHEN k.f_floor < c.pz THEN k.fsec    ELSE k.carried_floor_sec   END AS sector_id,
    CASE WHEN k.f_floor < c.pz THEN k.f_floor ELSE k.carried_floor_z     END AS plane_z,
    CASE WHEN k.f_floor < c.pz THEN k.f_light ELSE k.carried_floor_light END AS sector_light,
    FALSE AS is_sky,
    'floor'::text AS plane, 1::int AS source_priority,
    b.y0,
    LEAST(rs.screen_h - 1, k.fc_before) AS y1
  FROM panel_clips k
  CROSS JOIN render_settings rs
  CROSS JOIN cam c
  CROSS JOIN LATERAL (
    SELECT FLOOR(LEAST(rs.screen_h - 1.0, GREATEST(0.0,
      CASE
        WHEN k.f_floor < c.pz THEN k.f_floor_y_f
        ELSE GREATEST(k.f_floor_y_f,
                      rs.cy - rs.focal * (k.carried_floor_z - c.pz)
                              / rs.max_plane_depth)
      END
    )))::int + 1 AS y0
  ) b
  WHERE k.part IN ('solid','midmask','lower','lower_down')
    AND b.y0 <= k.fc_before
    AND (k.f_floor < c.pz OR k.fc_before < rs.screen_h - 1)
  UNION ALL
  -- Seed the floor immediately around the camera.
  -- It continues until it reaches the nearest wall depth.
  SELECT
    x AS col_x,
    ps.id AS sector_id,
    ps.floor_height AS plane_z,
    ps.light_level AS sector_light,
    FALSE AS is_sky,
    'floor'::text AS plane,
    0::int AS source_priority,
    CASE WHEN np.depth_x IS NULL THEN FLOOR(rs.cy)::int + 1
         ELSE FLOOR(LEAST(rs.screen_h - 1.0, GREATEST(0.0,
           rs.cy - rs.focal * (ps.floor_height - c.pz) / np.depth_x
         )))::int + 1
    END AS y0,
    rs.screen_h - 1 AS y1
  FROM render_settings rs
  CROSS JOIN cam c
  CROSS JOIN player_sector ps
  CROSS JOIN LATERAL generate_series((0) + ((0) & 1), rs.screen_w - 1, 2) AS x
  LEFT JOIN (SELECT n.col_x, n.floor_depth AS depth_x FROM nearest_panels n) np ON np.col_x = x
  UNION ALL
  -- Same for the ceiling.
  SELECT
    x AS col_x,
    ps.id AS sector_id,
    ps.ceil_height AS plane_z,
    ps.light_level AS sector_light,
    (ps.ceil_tex = 'F_SKY1') AS is_sky,
    'ceil'::text AS plane,
    0::int AS source_priority,
    0 AS y0,
    CASE WHEN np.depth_x IS NULL THEN CEIL(rs.cy)::int - 1
         ELSE CEIL(LEAST(rs.screen_h - 1.0, GREATEST(0.0,
           rs.cy - rs.focal * (ps.ceil_height - c.pz) / np.depth_x
         )))::int - 1
    END AS y1
  FROM render_settings rs
  CROSS JOIN cam c
  CROSS JOIN player_sector ps
  CROSS JOIN LATERAL generate_series((0) + ((0) & 1), rs.screen_w - 1, 2) AS x
  LEFT JOIN (SELECT n.col_x, n.ceil_depth AS depth_x FROM nearest_panels n) np ON np.col_x = x
),
plane_spans AS (
  -- A floor is only ever the top surface, visible from above (pz > plane_z);
  -- a ceiling is only ever the underside, visible from below (pz < plane_z).
  SELECT ps.*
  FROM plane_spans_raw ps
  CROSS JOIN cam c
  -- Vanilla's one exception (R_StoreWallRange): a ceiling below the viewer is
  -- skipped as "below view plane" ONLY when it is not the sky flat.
  WHERE (ps.plane = 'floor' AND ps.plane_z < c.pz)
     OR (ps.plane = 'ceil'  AND (ps.plane_z > c.pz OR ps.is_sky))
),
plane_spans_deduped AS (
  -- The near-camera seed and the nearest wall's front plane describe the same surface over the same rows.
  -- Collapse identical spans of one surface (same column, sector, height and side) before they are
  -- expanded: ~2k span rows instead of ~90k pixel rows.
  SELECT col_x, sector_id, plane_z, plane, is_sky, y0, y1,
         MIN(sector_light)    AS sector_light,
         MIN(source_priority) AS source_priority
  FROM plane_spans
  WHERE y1 >= y0
  GROUP BY col_x, sector_id, plane_z, plane, is_sky, y0, y1
),
plane_span_info AS MATERIALIZED (
  -- Everything about a span that is constant down its column, looked up once
  -- per span (~1-2k rows) instead of once per pixel (~27k): the sector's flat
  -- (or the sky), the column's ray and its sky column, the key bits other
  -- than depth, light and texel (see view_lanes), and the row of
  -- doom_zlight_lut its pixels' light comes from: the sector's light step
  -- (15 - clamp(floor(l/16) + e), the per-span part of doom_light_index), or
  -- the fixed light of the sky or of invulnerability. zk is the span's depth
  -- class, its plane's height or -1000000 for the sky, whose depth is one far
  -- sentinel. MATERIALIZED, for plane_depths and plane_lanes both, and without
  -- the textures' bytes, which a stored row would copy: plane_lanes joins
  -- them. CedarDB's version joined sectors, flats and the sky texture per
  -- pixel; in Postgres those three hash probes were most of the plane cost.
  SELECT ps.col_x, ps.y0, ps.y1,
         ps.is_sky AS span_is_sky,       -- the panel's view: sets the depth
         CASE WHEN ps.is_sky THEN -1000000 ELSE ps.plane_z END AS zk,
         t.tex_name,
         (t.tex_name = 'F_SKY1') AS is_sky, -- the sector's flat: picks the sampler
         -- Which texel a lane reads, one test: a whole flat, a whole sky, a
         -- flat or sky checked per pixel, or none (0).
         CASE WHEN NOT (t.tex_name = 'F_SKY1') AND ft.whole THEN 0
              WHEN (t.tex_name = 'F_SKY1') AND sk.whole THEN 1
              WHEN NOT (t.tex_name = 'F_SKY1') AND ft.name IS NOT NULL THEN 2
              WHEN (t.tex_name = 'F_SKY1') AND sk.present THEN 3
              ELSE 4 END AS sampler,
         sk.width AS sky_w,
         t.tan_alpha,
         CASE WHEN (t.tex_name = 'F_SKY1') THEN
           ((FLOOR(degrees(c.view_rad - ATAN(t.tan_alpha)) * (rs.sky_columns/rs.sky_degrees))::int
             % rs.sky_columns::int) + rs.sky_columns::int) % rs.sky_columns::int END AS sky_u,
         ((2::bigint - 0::bigint) << 32)
         | (LEAST(ps.source_priority::bigint, 3::bigint) << 30)
         | (LEAST(65535::bigint, GREATEST(0::bigint,
             (ps.sector_id::bigint*2
              + CASE WHEN ps.plane='floor' THEN 0 ELSE 1 END)::bigint + 32768)) << 14)
           AS key_hi,
         -- Sky is drawn unlit; invulnerability fixes the colormap.
         CASE WHEN (t.tex_name = 'F_SKY1') THEN 16 WHEN wr.invuln THEN 17
              ELSE 15 - LEAST(15, GREATEST(0, FLOOR(ps.sector_light::float8 / 16.0)::int
                                              + wr.extra_light))
         END * 128 AS light_row
  FROM plane_spans_deduped ps
  CROSS JOIN render_context rc
  CROSS JOIN render_settings rs
  CROSS JOIN cam c
  CROSS JOIN weapon_runtime wr
  JOIN sectors_lit s ON s.id = ps.sector_id AND s.map_id = rc.map_id
  CROSS JOIN LATERAL (
    SELECT CASE WHEN ps.plane = 'floor' THEN s.floor_tex ELSE s.ceil_tex END AS tex_name,
           (ps.col_x - rs.cx) / rs.focal AS tan_alpha
  ) t
  LEFT JOIN (SELECT f.name, OCTET_LENGTH(f.palette_indices) >= rs2.flat_size * rs2.flat_size AS whole
             FROM frame_flats f CROSS JOIN render_settings rs2) ft
    ON t.tex_name <> 'F_SKY1' AND ft.name = t.tex_name
  CROSS JOIN frame_sky sk
),
plane_depths AS (
  -- invert the wall projection: y_screen = cy - focal*(z-pz)/x_view
  -- => x_view (depth) = focal*(plane_z - pz)/(cy - y)
  -- A lane's depth, whether it is drawn (in front of the near plane, or sky),
  -- its key's depth and light bits and the camera's part of its flat
  -- coordinates depend only on the plane's height, the span's light row and
  -- the screen row: so they are worked out here once for every cell row g a
  -- height and light row has spans in (~300 rows), and not in each of the
  -- ~2,000-8,000 plane cells that read them. The inner query gives each
  -- lane's depth once (OFFSET 0: inlined, it would be computed at each use).
  SELECT q.zk, q.light_row, q.g,
         (q.zk = -1000000 OR q.d0 > rs.near) AS ok0,
         CASE WHEN q.zk = -1000000 OR q.d0 > rs.near THEN
           ((LEAST(q.d0, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d0 / 16.0)::int))::bigint << 8)
         END AS kl0,
         q.d0, c.px + q.d0 * c.cos_v AS a0, c.py + q.d0 * c.sin_v AS b0,
         (q.zk = -1000000 OR q.d1 > rs.near) AS ok1,
         CASE WHEN q.zk = -1000000 OR q.d1 > rs.near THEN
           ((LEAST(q.d1, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d1 / 16.0)::int))::bigint << 8)
         END AS kl1,
         q.d1, c.px + q.d1 * c.cos_v AS a1, c.py + q.d1 * c.sin_v AS b1,
         (q.zk = -1000000 OR q.d2 > rs.near) AS ok2,
         CASE WHEN q.zk = -1000000 OR q.d2 > rs.near THEN
           ((LEAST(q.d2, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d2 / 16.0)::int))::bigint << 8)
         END AS kl2,
         q.d2, c.px + q.d2 * c.cos_v AS a2, c.py + q.d2 * c.sin_v AS b2,
         (q.zk = -1000000 OR q.d3 > rs.near) AS ok3,
         CASE WHEN q.zk = -1000000 OR q.d3 > rs.near THEN
           ((LEAST(q.d3, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d3 / 16.0)::int))::bigint << 8)
         END AS kl3,
         q.d3, c.px + q.d3 * c.cos_v AS a3, c.py + q.d3 * c.sin_v AS b3,
         (q.zk = -1000000 OR q.d4 > rs.near) AS ok4,
         CASE WHEN q.zk = -1000000 OR q.d4 > rs.near THEN
           ((LEAST(q.d4, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d4 / 16.0)::int))::bigint << 8)
         END AS kl4,
         q.d4, c.px + q.d4 * c.cos_v AS a4, c.py + q.d4 * c.sin_v AS b4,
         (q.zk = -1000000 OR q.d5 > rs.near) AS ok5,
         CASE WHEN q.zk = -1000000 OR q.d5 > rs.near THEN
           ((LEAST(q.d5, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d5 / 16.0)::int))::bigint << 8)
         END AS kl5,
         q.d5, c.px + q.d5 * c.cos_v AS a5, c.py + q.d5 * c.sin_v AS b5,
         (q.zk = -1000000 OR q.d6 > rs.near) AS ok6,
         CASE WHEN q.zk = -1000000 OR q.d6 > rs.near THEN
           ((LEAST(q.d6, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d6 / 16.0)::int))::bigint << 8)
         END AS kl6,
         q.d6, c.px + q.d6 * c.cos_v AS a6, c.py + q.d6 * c.sin_v AS b6,
         (q.zk = -1000000 OR q.d7 > rs.near) AS ok7,
         CASE WHEN q.zk = -1000000 OR q.d7 > rs.near THEN
           ((LEAST(q.d7, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d7 / 16.0)::int))::bigint << 8)
         END AS kl7,
         q.d7, c.px + q.d7 * c.cos_v AS a7, c.py + q.d7 * c.sin_v AS b7,
         (q.zk = -1000000 OR q.d8 > rs.near) AS ok8,
         CASE WHEN q.zk = -1000000 OR q.d8 > rs.near THEN
           ((LEAST(q.d8, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d8 / 16.0)::int))::bigint << 8)
         END AS kl8,
         q.d8, c.px + q.d8 * c.cos_v AS a8, c.py + q.d8 * c.sin_v AS b8,
         (q.zk = -1000000 OR q.d9 > rs.near) AS ok9,
         CASE WHEN q.zk = -1000000 OR q.d9 > rs.near THEN
           ((LEAST(q.d9, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d9 / 16.0)::int))::bigint << 8)
         END AS kl9,
         q.d9, c.px + q.d9 * c.cos_v AS a9, c.py + q.d9 * c.sin_v AS b9,
         (q.zk = -1000000 OR q.d10 > rs.near) AS ok10,
         CASE WHEN q.zk = -1000000 OR q.d10 > rs.near THEN
           ((LEAST(q.d10, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d10 / 16.0)::int))::bigint << 8)
         END AS kl10,
         q.d10, c.px + q.d10 * c.cos_v AS a10, c.py + q.d10 * c.sin_v AS b10,
         (q.zk = -1000000 OR q.d11 > rs.near) AS ok11,
         CASE WHEN q.zk = -1000000 OR q.d11 > rs.near THEN
           ((LEAST(q.d11, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d11 / 16.0)::int))::bigint << 8)
         END AS kl11,
         q.d11, c.px + q.d11 * c.cos_v AS a11, c.py + q.d11 * c.sin_v AS b11,
         (q.zk = -1000000 OR q.d12 > rs.near) AS ok12,
         CASE WHEN q.zk = -1000000 OR q.d12 > rs.near THEN
           ((LEAST(q.d12, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d12 / 16.0)::int))::bigint << 8)
         END AS kl12,
         q.d12, c.px + q.d12 * c.cos_v AS a12, c.py + q.d12 * c.sin_v AS b12,
         (q.zk = -1000000 OR q.d13 > rs.near) AS ok13,
         CASE WHEN q.zk = -1000000 OR q.d13 > rs.near THEN
           ((LEAST(q.d13, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d13 / 16.0)::int))::bigint << 8)
         END AS kl13,
         q.d13, c.px + q.d13 * c.cos_v AS a13, c.py + q.d13 * c.sin_v AS b13,
         (q.zk = -1000000 OR q.d14 > rs.near) AS ok14,
         CASE WHEN q.zk = -1000000 OR q.d14 > rs.near THEN
           ((LEAST(q.d14, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d14 / 16.0)::int))::bigint << 8)
         END AS kl14,
         q.d14, c.px + q.d14 * c.cos_v AS a14, c.py + q.d14 * c.sin_v AS b14,
         (q.zk = -1000000 OR q.d15 > rs.near) AS ok15,
         CASE WHEN q.zk = -1000000 OR q.d15 > rs.near THEN
           ((LEAST(q.d15, 131071.0)*4096)::bigint << 34)
           | (GET_BYTE(doom_zlight_lut(), q.light_row + LEAST(127, FLOOR(q.d15 / 16.0)::int))::bigint << 8)
         END AS kl15,
         q.d15, c.px + q.d15 * c.cos_v AS a15, c.py + q.d15 * c.sin_v AS b15
  FROM (
    SELECT k.zk, k.light_row, k.g,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+0), 0.0) END AS d0,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+1), 0.0) END AS d1,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+2), 0.0) END AS d2,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+3), 0.0) END AS d3,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+4), 0.0) END AS d4,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+5), 0.0) END AS d5,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+6), 0.0) END AS d6,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+7), 0.0) END AS d7,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+8), 0.0) END AS d8,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+9), 0.0) END AS d9,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+10), 0.0) END AS d10,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+11), 0.0) END AS d11,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+12), 0.0) END AS d12,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+13), 0.0) END AS d13,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+14), 0.0) END AS d14,
           CASE WHEN k.zk = -1000000 THEN 1e7::float8
                ELSE (rs.focal * (k.zk - c.pz)) / NULLIF(rs.cy - (k.g*16+15), 0.0) END AS d15
    -- (A series of constant bounds, filtered: one of a span's bounds would be
    -- estimated at 1,000 rows a call, and the join below planned for that.)
    FROM (SELECT r.zk, r.light_row, gs.g
          FROM (SELECT i.zk, i.light_row, MIN(i.y0) >> 4 AS g0, MAX(i.y1) >> 4 AS g1
                FROM plane_span_info i
                GROUP BY i.zk, i.light_row) r
          CROSS JOIN generate_series(0, 10) AS gs(g)
          WHERE gs.g BETWEEN r.g0 AND r.g1) k
    CROSS JOIN render_settings rs
    CROSS JOIN cam c
    OFFSET 0
  ) q
  CROSS JOIN render_settings rs
  CROSS JOIN cam c
),
plane_lanes AS (
  -- Sixteen plane pixels a row, as wall_lanes: each lane from its row's
  -- plane_depths and the span's own column, straight to texture
  -- coordinates, the flat's or the sky's texel, and the key. The
  -- coordinates' sums keep the order of u = px + d*cos + (tan * d)*sin, so
  -- each texel is the one it always was.
  SELECT p.col_x AS x, p.g,
    CASE WHEN (p.g*16+0) BETWEEN p.y0 AND p.y1 AND pd.ok0 THEN pd.kl0 | p.key_hi
      | (CASE p.sampler
          WHEN 0 THEN GET_BYTE(p.flat_pi, ((FLOOR(pd.b0 - (p.tan_alpha * pd.d0) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a0 + (p.tan_alpha * pd.d0) * c.sin_v)::int & (rs.flat_size - 1))))
          WHEN 1 THEN GET_BYTE(p.sky_pi, ((((p.g*16+0) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u))
          WHEN 2 THEN CASE WHEN ((FLOOR(pd.b0 - (p.tan_alpha * pd.d0) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a0 + (p.tan_alpha * pd.d0) * c.sin_v)::int & (rs.flat_size - 1))) >= 0 AND ((FLOOR(pd.b0 - (p.tan_alpha * pd.d0) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a0 + (p.tan_alpha * pd.d0) * c.sin_v)::int & (rs.flat_size - 1))) < OCTET_LENGTH(p.flat_pi) THEN GET_BYTE(p.flat_pi, ((FLOOR(pd.b0 - (p.tan_alpha * pd.d0) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a0 + (p.tan_alpha * pd.d0) * c.sin_v)::int & (rs.flat_size - 1)))) ELSE 0 END
          WHEN 3 THEN CASE WHEN ((((p.g*16+0) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u) >= 0 AND ((((p.g*16+0) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u) < OCTET_LENGTH(p.sky_pi) THEN GET_BYTE(p.sky_pi, ((((p.g*16+0) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u)) ELSE 0 END
          ELSE 0 END)::bigint END AS k0,
    CASE WHEN (p.g*16+1) BETWEEN p.y0 AND p.y1 AND pd.ok1 THEN pd.kl1 | p.key_hi
      | (CASE p.sampler
          WHEN 0 THEN GET_BYTE(p.flat_pi, ((FLOOR(pd.b1 - (p.tan_alpha * pd.d1) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a1 + (p.tan_alpha * pd.d1) * c.sin_v)::int & (rs.flat_size - 1))))
          WHEN 1 THEN GET_BYTE(p.sky_pi, ((((p.g*16+1) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u))
          WHEN 2 THEN CASE WHEN ((FLOOR(pd.b1 - (p.tan_alpha * pd.d1) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a1 + (p.tan_alpha * pd.d1) * c.sin_v)::int & (rs.flat_size - 1))) >= 0 AND ((FLOOR(pd.b1 - (p.tan_alpha * pd.d1) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a1 + (p.tan_alpha * pd.d1) * c.sin_v)::int & (rs.flat_size - 1))) < OCTET_LENGTH(p.flat_pi) THEN GET_BYTE(p.flat_pi, ((FLOOR(pd.b1 - (p.tan_alpha * pd.d1) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a1 + (p.tan_alpha * pd.d1) * c.sin_v)::int & (rs.flat_size - 1)))) ELSE 0 END
