          WHEN 2 THEN CASE WHEN ((FLOOR(pd.b13 - (p.tan_alpha * pd.d13) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a13 + (p.tan_alpha * pd.d13) * c.sin_v)::int & (rs.flat_size - 1))) >= 0 AND ((FLOOR(pd.b13 - (p.tan_alpha * pd.d13) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a13 + (p.tan_alpha * pd.d13) * c.sin_v)::int & (rs.flat_size - 1))) < OCTET_LENGTH(p.flat_pi) THEN GET_BYTE(p.flat_pi, ((FLOOR(pd.b13 - (p.tan_alpha * pd.d13) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a13 + (p.tan_alpha * pd.d13) * c.sin_v)::int & (rs.flat_size - 1)))) ELSE 0 END
          WHEN 3 THEN CASE WHEN ((((p.g*16+13) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u) >= 0 AND ((((p.g*16+13) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u) < OCTET_LENGTH(p.sky_pi) THEN GET_BYTE(p.sky_pi, ((((p.g*16+13) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u)) ELSE 0 END
          ELSE 0 END)::bigint END AS k13,
    CASE WHEN (p.g*16+14) BETWEEN p.y0 AND p.y1 AND pd.ok14 THEN pd.kl14 | p.key_hi
      | (CASE p.sampler
          WHEN 0 THEN GET_BYTE(p.flat_pi, ((FLOOR(pd.b14 - (p.tan_alpha * pd.d14) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a14 + (p.tan_alpha * pd.d14) * c.sin_v)::int & (rs.flat_size - 1))))
          WHEN 1 THEN GET_BYTE(p.sky_pi, ((((p.g*16+14) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u))
          WHEN 2 THEN CASE WHEN ((FLOOR(pd.b14 - (p.tan_alpha * pd.d14) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a14 + (p.tan_alpha * pd.d14) * c.sin_v)::int & (rs.flat_size - 1))) >= 0 AND ((FLOOR(pd.b14 - (p.tan_alpha * pd.d14) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a14 + (p.tan_alpha * pd.d14) * c.sin_v)::int & (rs.flat_size - 1))) < OCTET_LENGTH(p.flat_pi) THEN GET_BYTE(p.flat_pi, ((FLOOR(pd.b14 - (p.tan_alpha * pd.d14) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a14 + (p.tan_alpha * pd.d14) * c.sin_v)::int & (rs.flat_size - 1)))) ELSE 0 END
          WHEN 3 THEN CASE WHEN ((((p.g*16+14) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u) >= 0 AND ((((p.g*16+14) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u) < OCTET_LENGTH(p.sky_pi) THEN GET_BYTE(p.sky_pi, ((((p.g*16+14) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u)) ELSE 0 END
          ELSE 0 END)::bigint END AS k14,
    CASE WHEN (p.g*16+15) BETWEEN p.y0 AND p.y1 AND pd.ok15 THEN pd.kl15 | p.key_hi
      | (CASE p.sampler
          WHEN 0 THEN GET_BYTE(p.flat_pi, ((FLOOR(pd.b15 - (p.tan_alpha * pd.d15) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a15 + (p.tan_alpha * pd.d15) * c.sin_v)::int & (rs.flat_size - 1))))
          WHEN 1 THEN GET_BYTE(p.sky_pi, ((((p.g*16+15) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u))
          WHEN 2 THEN CASE WHEN ((FLOOR(pd.b15 - (p.tan_alpha * pd.d15) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a15 + (p.tan_alpha * pd.d15) * c.sin_v)::int & (rs.flat_size - 1))) >= 0 AND ((FLOOR(pd.b15 - (p.tan_alpha * pd.d15) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a15 + (p.tan_alpha * pd.d15) * c.sin_v)::int & (rs.flat_size - 1))) < OCTET_LENGTH(p.flat_pi) THEN GET_BYTE(p.flat_pi, ((FLOOR(pd.b15 - (p.tan_alpha * pd.d15) * c.cos_v)::int & (rs.flat_size - 1)) * rs.flat_size + (FLOOR(pd.a15 + (p.tan_alpha * pd.d15) * c.sin_v)::int & (rs.flat_size - 1)))) ELSE 0 END
          WHEN 3 THEN CASE WHEN ((((p.g*16+15) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u) >= 0 AND ((((p.g*16+15) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u) < OCTET_LENGTH(p.sky_pi) THEN GET_BYTE(p.sky_pi, ((((p.g*16+15) - rs.sky_horizon_y) & (rs.sky_rows - 1)) * p.sky_w + p.sky_u)) ELSE 0 END
          ELSE 0 END)::bigint END AS k15
  FROM (SELECT si.col_x, si.y0, si.y1, si.zk, si.light_row, si.key_hi, si.sampler,
               si.sky_w, si.sky_u, si.tan_alpha,
               ft.palette_indices AS flat_pi,
               -- (a scalar subquery: evaluated once, where a join rescans
               -- frame_sky for every span)
               CASE WHEN si.is_sky THEN (SELECT f.pi FROM frame_sky f) END AS sky_pi,
               generate_series(si.y0 >> 4, si.y1 >> 4) AS g
        FROM plane_span_info si
        LEFT JOIN frame_flats ft ON NOT si.is_sky AND ft.name = si.tex_name) p
  JOIN plane_depths pd ON pd.zk = p.zk AND pd.light_row = p.light_row AND pd.g = p.g
  CROSS JOIN render_settings rs
  CROSS JOIN cam c
),

-- Next up: Sprites.
-- In Doom, they're just called things.
-- Each thing is just a 2D sprite that always faces you (so no real 3D object).
-- Their BSP-resolved sector and initial state sprite are pre-materialized at load time
-- in render_things
-- We only have to do view projection, select the right sprite variant (depending on the direction),
-- do sparse opaque-pixel sampling, and do the depth resolve.
thing_view AS (
  SELECT
    t.id::bigint AS thing_id, t.x::real, t.y::real, t.angle,
    -- Sprite lump name never changes across a monster's own states.
    -- Only the frame letter changes. Vanilla Doom always keeps one 4-letter
    -- sprite per mobj type. It only ever changes for the terminal death
    -- sprite (e.g. exploding barrels: BAR1 -> BEXP).
    CASE WHEN COALESCE(d.explodes, FALSE) AND ai.state='die' THEN d.death_sprite
         WHEN h.alive = FALSE AND (ai.state IS NULL OR ai.state = 'dead')
         THEN d.death_sprite ELSE rt.sprite END AS sprite,
    -- A gibbed corpse has a special frame (def. an 18+ game back in the day).
    CASE WHEN h.alive = FALSE AND (ai.state IS NULL OR ai.state = 'dead')
           THEN CASE WHEN h.health < -h.max_health AND d.xdeath_frame IS NOT NULL
                     THEN d.xdeath_frame ELSE d.death_frame END
         WHEN f.frame IS NOT NULL THEN f.frame
         ELSE rt.frame END AS frame,
    CASE WHEN h.alive = FALSE AND (ai.state IS NULL OR ai.state = 'dead')
           THEN d.death_fullbright
         WHEN f.frame IS NOT NULL THEN f.fullbright
         ELSE rt.fullbright END AS fullbright,
    CASE WHEN rt.spawn_ceiling THEN s.ceil_height - rt.thing_height
         -- a live floater is drawn where it hovers; a dead one has dropped
         WHEN d.floats AND COALESCE(h.alive, TRUE) THEN t.z
         ELSE s.floor_height END::real AS base_z,
    s.floor_height, s.ceil_height, s.light_level AS sector_light,
    (t.x - c.px) * COS(c.view_rad)
      + (t.y - c.py) * SIN(c.view_rad) AS depth,
    (t.x - c.px) * SIN(c.view_rad)
      - (t.y - c.py) * COS(c.view_rad) AS side,
    (((FLOOR((
        DEGREES(ATAN2(t.y - c.py, t.x - c.px))
        - t.angle + rs.rotation_offset
      ) / rs.rotation_span)::int % 8) + 8) % 8 + 1)::smallint AS wanted_rotation,
    COALESCE(d.fuzzy, FALSE) AS fuzz
  FROM render_things rt
  CROSS JOIN render_context rc
  CROSS JOIN render_settings rs
  JOIN things t ON t.map_id = rt.map_id AND t.id = rt.thing_id
  LEFT JOIN thing_health h ON h.map_id = rt.map_id AND h.thing_id = rt.thing_id
  LEFT JOIN thing_combat_defs d ON d.thing_type = t.type
  -- Live AI state overrides the static spawn placement once a monster has
  -- been ticked (sector_id starts NULL and only gets set once it moves).
  LEFT JOIN monster_ai ai ON ai.map_id = rt.map_id AND ai.thing_id = rt.thing_id
  LEFT JOIN thing_ai_frames f ON f.thing_type = t.type AND f.state = ai.state
    AND f.seq_index = ai.seq_index
  -- Collected pickups stop rendering entirely
  LEFT JOIN picked_up_items pu ON pu.map_id = rt.map_id AND pu.thing_id = rt.thing_id
  JOIN sectors_lit s ON s.map_id = rt.map_id AND s.id = COALESCE(ai.sector_id, rt.sector_id)
  CROSS JOIN cam c
  WHERE rt.map_id = rc.map_id
    -- Single-player spawn filtering from Doom Thing options, gated by the
    -- client's selected difficulty (rc.skill_bit: 1/2/4, derived from the
    -- 0..4 skill).
    AND (t.flags & rc.skill_bit) <> 0
    AND (t.flags & 16) = 0
    AND pu.thing_id IS NULL
    -- Vanilla removes a barrel after BEXP E; other corpses remain visible.
    AND NOT (COALESCE(d.explodes, FALSE) AND ai.state='dead')
  UNION ALL
  SELECT
    -e.effect_id AS thing_id, e.x, e.y, 0::smallint,
    ed.sprite,
    -- One letter per tics_per_frame
    SUBSTRING(ed.frame_sequence
              FROM LEAST(LENGTH(ed.frame_sequence) - 1,
                         e.age / ed.tics_per_frame) + 1 FOR 1),
    ed.fullbright, e.z,
    s.floor_height, s.ceil_height, COALESCE(s.light_level, ps.light_level),
    (e.x - c.px) * COS(c.view_rad) + (e.y - c.py) * SIN(c.view_rad),
    (e.x - c.px) * SIN(c.view_rad) - (e.y - c.py) * COS(c.view_rad),
    0::smallint, FALSE
  FROM world_effects e
  CROSS JOIN render_context rc
  CROSS JOIN cam c
  CROSS JOIN player_sector ps
  JOIN effect_sprite_defs ed ON ed.effect_type = e.effect_type
  LEFT JOIN sectors_lit s ON s.map_id=e.map_id AND s.id=e.sector_id
  WHERE e.map_id=rc.map_id
  UNION ALL
  -- The other players of a deathmatch.
  -- A blur sphere makes them fuzzy like a spectre.
  SELECT
    ot.id::bigint, ot.x::real, ot.y::real, ot.angle,
    'PLAY'::varchar(4), op.sprite_frame, FALSE,
    s.floor_height::real, s.floor_height, s.ceil_height, s.light_level,
    (ot.x - c.px) * COS(c.view_rad) + (ot.y - c.py) * SIN(c.view_rad),
    (ot.x - c.px) * SIN(c.view_rad) - (ot.y - c.py) * COS(c.view_rad),
    (((FLOOR((DEGREES(ATAN2(ot.y - c.py, ot.x - c.px))
        - ot.angle + rs.rotation_offset) / rs.rotation_span)::int % 8)
        + 8) % 8 + 1)::smallint,
    (op.invis_tics > 0)
  FROM player_state op
  CROSS JOIN render_context rc
  CROSS JOIN render_settings rs
  JOIN things ot ON ot.map_id = op.map_id AND ot.id = op.player_thing_id
  JOIN sectors_lit s ON s.map_id = op.map_id AND s.id = op.sector_id
  CROSS JOIN cam c
  WHERE op.map_id = rc.map_id AND op.player_thing_id <> rc.player_thing_id AND (op.alive OR EXISTS (SELECT 1 FROM mp_players mx WHERE mx.map_id = op.map_id AND mx.player_thing_id = op.player_thing_id AND mx.role_name IS NOT NULL))
  UNION ALL
  SELECT
    -(1000000000000::bigint+mp.projectile_id) AS thing_id,
    mp.x,mp.y,DEGREES(ATAN2(mp.vy,mp.vx))::smallint,
    (CASE WHEN mp.state='fly' THEN pd.fly_sprite
          ELSE pd.impact_sprite END)::varchar(4),
    CASE
      WHEN mp.projectile_type='rocket' THEN
        CASE WHEN mp.state='fly' THEN 'A' WHEN mp.age<8 THEN 'B'
             WHEN mp.age<14 THEN 'C' ELSE 'D' END
      WHEN mp.projectile_type='plasma' THEN
        CASE WHEN mp.state='fly' THEN CASE WHEN (mp.age%12)<6 THEN 'A' ELSE 'B' END
             WHEN mp.age<4 THEN 'A' WHEN mp.age<8 THEN 'B'
             WHEN mp.age<12 THEN 'C' WHEN mp.age<16 THEN 'D' ELSE 'E' END
      WHEN mp.projectile_type='bfg' THEN
        CASE WHEN mp.state='fly' THEN CASE WHEN (mp.age%8)<4 THEN 'A' ELSE 'B' END
             WHEN mp.age<8 THEN 'A' WHEN mp.age<16 THEN 'B'
             WHEN mp.age<24 THEN 'C' WHEN mp.age<32 THEN 'D'
             WHEN mp.age<40 THEN 'E' ELSE 'F' END
      ELSE CASE WHEN mp.state='fly'
             THEN CASE WHEN (mp.age%8)<4 THEN 'A' ELSE 'B' END
             WHEN mp.age<5 THEN 'C' WHEN mp.age<10 THEN 'D' ELSE 'E' END
    END,
    TRUE,mp.z,
    COALESCE(s.floor_height,ps.floor_height),
    COALESCE(s.ceil_height,ps.ceil_height),
    COALESCE(s.light_level,ps.light_level),
    (mp.x-c.px)*COS(c.view_rad)+(mp.y-c.py)*SIN(c.view_rad),
    (mp.x-c.px)*SIN(c.view_rad)-(mp.y-c.py)*COS(c.view_rad),
    CASE WHEN mp.state='fly' THEN
      (((FLOOR((DEGREES(ATAN2(mp.y-c.py,mp.x-c.px))
          -DEGREES(ATAN2(mp.vy,mp.vx))+rs.rotation_offset)
          /rs.rotation_span)::int%8)+8)%8+1)::smallint
      ELSE 0::smallint END, FALSE
  FROM monster_projectiles mp
  CROSS JOIN render_context rc
  CROSS JOIN render_settings rs
  CROSS JOIN cam c
  CROSS JOIN player_sector ps
  JOIN projectile_defs pd ON pd.projectile_type = mp.projectile_type
  LEFT JOIN sectors_lit s ON s.map_id=mp.map_id AND s.id=mp.sector_id
  WHERE mp.map_id=rc.map_id
),
thing_projected AS MATERIALIZED (
  -- Each thing in front of the camera with the sprite frame it shows. Its
  -- pixels are fetched in thing_spans, once it is known to be on screen.
  SELECT
    tv.*, sf.lump_name, sf.flipped, sf.width, sf.height,
    sf.left_offset, sf.top_offset,
    rs.focal / tv.depth AS scale,
    rs.cx + rs.focal * tv.side / tv.depth AS origin_x
  FROM thing_view tv
  CROSS JOIN render_settings rs
  -- The frame's own rotation if it has the one wanted, else its rotation 0
  -- (sprite_rotations, made at load time): a probe, where a lookup of
  -- sprite_frames per thing was an index scan and a sort.
  JOIN sprite_rotations sf ON sf.sprite = tv.sprite AND sf.frame = tv.frame
    AND sf.wanted_rotation = tv.wanted_rotation
  WHERE tv.depth >= 4.0
    -- Coarse reject leaves room for wide sprites whose origin is off-screen.
    AND ABS(tv.side) <= tv.depth * 2.0
),
thing_bounds AS (
  SELECT
    tp.*,
    tp.origin_x - tp.scale * tp.left_offset AS x_left_f,
    tp.origin_x + tp.scale * (tp.width - tp.left_offset) AS x_right_f,
    rs.cy - tp.scale * (tp.base_z + tp.top_offset - c.pz) AS y_top_f,
    rs.cy - tp.scale
      * (tp.base_z + tp.top_offset - tp.height - c.pz) AS y_bottom_f
  FROM thing_projected tp
  CROSS JOIN render_settings rs
  CROSS JOIN cam c
),
thing_bounds_lit AS (
  -- A sprite's shade is per thing, not per pixel: one depth, one sector
  -- light. ~50 things instead of ~8,000 pixels through the light arithmetic.
  SELECT tb.*,
         CASE WHEN wr.invuln THEN rs.light_index_invuln
              WHEN tb.fullbright THEN 0
              ELSE doom_light_index(tb.sector_light, wr.extra_light,
                                    doom_light_scale(tb.depth))
         END AS base_light
  FROM thing_bounds tb
  CROSS JOIN weapon_runtime wr CROSS JOIN render_settings rs
),
thing_spans AS (
  -- A visible sprite's screen box and its player colour slot, once per
  -- thing. The sprite pixel stages are subqueries of their own (OFFSET 0) for
  -- the reason wall_spans gives: what is constant per thing, per column or
  -- per pixel is computed once at that level instead of wherever it is used.
  -- The sprite's pixels and mask, detoasted for the reason frame_walltex
  -- gives: once per visible thing, then sampled per pixel below.
  SELECT tb.*, mpl.slot AS mp_slot,
         (sl.pixels || ''::bytea) AS pixels, (sl.mask || ''::bytea) AS mask,
         -- The resolve key's bits that are the same all over the sprite: its
         -- depth, the surface (sprite) and its stable id (see view_lanes).
         ((GREATEST(0.0::float8, LEAST(tb.depth, 131071.0))*4096)::bigint << 34)
         | ((2::bigint - 1::bigint) << 32)
         | (LEAST(0::bigint, 3::bigint) << 30)
         | (LEAST(65535::bigint, GREATEST(0::bigint, tb.thing_id + 32768)) << 14) AS key_hi,
         GREATEST(0, FLOOR(tb.x_left_f)::int) AS x_lo,
         LEAST(rs.screen_w - 1, CEIL(tb.x_right_f)::int - 1) AS x_hi,
         GREATEST(0, FLOOR(tb.y_top_f)::int) AS y_lo,
         LEAST(rs.screen_h - 1, CEIL(tb.y_bottom_f)::int - 1) AS y_hi
  FROM thing_bounds_lit tb
  JOIN sprite_lumps sl ON sl.lump_name = tb.lump_name
  CROSS JOIN render_settings rs
  CROSS JOIN render_context rc
  LEFT JOIN mp_players mpl ON mpl.map_id = rc.map_id AND mpl.player_thing_id = tb.thing_id
  WHERE tb.x_right_f > 0 AND tb.x_left_f < rs.screen_w
    AND tb.y_bottom_f > 0 AND tb.y_top_f < rs.screen_h
  OFFSET 0
),
thing_columns AS (
  -- One row per screen column of a sprite, with the patch column it shows.
  SELECT c.thing_id, c.screen_x, c.depth, c.fuzz, c.base_light, c.mp_slot, c.key_hi,
         c.pixels, c.mask, c.width, c.height, c.y_top_f, c.scale, c.y_lo, c.y_hi,
         CASE WHEN c.flipped THEN c.width - 1 - uu.raw_u ELSE uu.raw_u END AS col_off
  FROM (SELECT t.thing_id, t.depth, t.fuzz, t.base_light, t.mp_slot, t.key_hi, t.pixels,
               t.mask, t.width, t.height, t.y_top_f, t.scale, t.y_lo, t.y_hi,
               t.flipped, t.x_left_f,
               generate_series((t.x_lo) + ((t.x_lo) & 1), t.x_hi, 2) AS screen_x
        FROM thing_spans t) c
  CROSS JOIN LATERAL (
    SELECT LEAST(c.width - 1, GREATEST(0,
             FLOOR((c.screen_x - c.x_left_f) / c.scale)::int)) AS raw_u
  ) uu
  OFFSET 0
),
sprite_lanes AS (
  -- Sixteen pixels of a sprite's column a row, as wall_lanes: the inner query
  -- finds each lane's offset into the patch (NULL off the box), the outer
  -- keeps the opaque ones. R_InitTranslationTables: the PLAY sprite's green
  -- range (0x70..0x7F) is remapped per player: Slot 2 indigo (0x60), 3 brown
  -- (0x40), 4 red (0x20). Doom draws a Spectre with R_DrawFuzzColumn: the
  -- sprite's own colour is discarded and the pixel is re-read from the
  -- screen a row away through colormap 6, which looks like a shimmer. A
  -- set-based renderer resolves all pixels at once and has no finished
  -- screen to sample, so this instead keeps the silhouette and drives it to
  -- near-black with a per-pixel wobble.
  SELECT s.screen_x AS x, s.g,
    CASE WHEN GET_BYTE(s.mask, s.o0) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+0) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o0) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o0) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o0) END)::bigint END AS k0,
    CASE WHEN GET_BYTE(s.mask, s.o1) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+1) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o1) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o1) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o1) END)::bigint END AS k1,
    CASE WHEN GET_BYTE(s.mask, s.o2) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+2) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o2) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o2) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o2) END)::bigint END AS k2,
    CASE WHEN GET_BYTE(s.mask, s.o3) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+3) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o3) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o3) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o3) END)::bigint END AS k3,
    CASE WHEN GET_BYTE(s.mask, s.o4) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+4) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o4) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o4) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o4) END)::bigint END AS k4,
    CASE WHEN GET_BYTE(s.mask, s.o5) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+5) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o5) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o5) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o5) END)::bigint END AS k5,
    CASE WHEN GET_BYTE(s.mask, s.o6) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+6) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o6) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o6) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o6) END)::bigint END AS k6,
    CASE WHEN GET_BYTE(s.mask, s.o7) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+7) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o7) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o7) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o7) END)::bigint END AS k7,
    CASE WHEN GET_BYTE(s.mask, s.o8) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+8) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o8) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o8) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o8) END)::bigint END AS k8,
    CASE WHEN GET_BYTE(s.mask, s.o9) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+9) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o9) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o9) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o9) END)::bigint END AS k9,
    CASE WHEN GET_BYTE(s.mask, s.o10) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+10) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o10) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o10) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o10) END)::bigint END AS k10,
    CASE WHEN GET_BYTE(s.mask, s.o11) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+11) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o11) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o11) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o11) END)::bigint END AS k11,
    CASE WHEN GET_BYTE(s.mask, s.o12) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+12) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o12) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o12) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o12) END)::bigint END AS k12,
    CASE WHEN GET_BYTE(s.mask, s.o13) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+13) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o13) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o13) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o13) END)::bigint END AS k13,
    CASE WHEN GET_BYTE(s.mask, s.o14) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+14) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o14) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o14) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o14) END)::bigint END AS k14,
    CASE WHEN GET_BYTE(s.mask, s.o15) <> 0 THEN s.key_hi
      | ((CASE WHEN s.fuzz THEN (26 + ((s.screen_x * 7 + (s.g*16+15) * 13 + s.depth::int) % 5))::int
               ELSE s.base_light END)::bigint << 8)
      | (CASE WHEN s.mp_slot > 1 AND GET_BYTE(s.pixels, s.o15) BETWEEN 112 AND 127
              THEN GET_BYTE(s.pixels, s.o15) - 112 + CASE s.mp_slot WHEN 2 THEN 96 WHEN 3 THEN 64 ELSE 32 END
              ELSE GET_BYTE(s.pixels, s.o15) END)::bigint END AS k15
  FROM (
    SELECT t.screen_x, t.g, t.key_hi, t.fuzz, t.depth, t.base_light, t.mp_slot,
           t.pixels, t.mask,
           CASE WHEN (t.g*16+0) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+0) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o0,
           CASE WHEN (t.g*16+1) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+1) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o1,
           CASE WHEN (t.g*16+2) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+2) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o2,
           CASE WHEN (t.g*16+3) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+3) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o3,
           CASE WHEN (t.g*16+4) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+4) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o4,
           CASE WHEN (t.g*16+5) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+5) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o5,
           CASE WHEN (t.g*16+6) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+6) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o6,
           CASE WHEN (t.g*16+7) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+7) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o7,
           CASE WHEN (t.g*16+8) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+8) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o8,
           CASE WHEN (t.g*16+9) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+9) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o9,
           CASE WHEN (t.g*16+10) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+10) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o10,
           CASE WHEN (t.g*16+11) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+11) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o11,
           CASE WHEN (t.g*16+12) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+12) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o12,
           CASE WHEN (t.g*16+13) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+13) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o13,
           CASE WHEN (t.g*16+14) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+14) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o14,
           CASE WHEN (t.g*16+15) BETWEEN t.y_lo AND t.y_hi THEN LEAST(t.height - 1, GREATEST(0,
             FLOOR(((t.g*16+15) - t.y_top_f) / t.scale)::int)) * t.width + t.col_off END AS o15
    FROM (SELECT c.screen_x, c.key_hi, c.fuzz, c.depth, c.base_light, c.mp_slot,
                 c.pixels, c.mask, c.width, c.height, c.y_top_f, c.scale, c.col_off,
                 c.y_lo, c.y_hi, generate_series(c.y_lo >> 4, c.y_hi >> 4) AS g
          FROM thing_columns c) t
    OFFSET 0
  ) s
),

-- HU_Drawer: the pickup line, in the small STCFN font at the top-left of the
-- view. Only the glyphs of the message join ui_patch_pixels, and only while
-- one is up -- an empty message makes every CTE below empty.
message_glyphs AS (
  SELECT gs.i AS pos,
         substring(UPPER(pu.message) FROM gs.i FOR 1) AS ch
  FROM player_ui_state pu
  CROSS JOIN LATERAL generate_series(1, length(pu.message)) AS gs(i)
  WHERE pu.message IS NOT NULL AND pu.message_tics > 0
),
message_placed AS (
  -- HUlib_drawTextLine walks the line accumulating each glyph's own width; a
  -- space has no patch and advances by 4.
  SELECT g.pos, g.ch,
         CASE WHEN g.ch = ' ' THEN NULL
              ELSE 'STCFN' || LPAD(ASCII(g.ch)::text, 3, '0') END AS patch,
         SUM(CASE WHEN g.ch = ' ' THEN 4
                  ELSE COALESCE((SELECT p.width FROM ui_patches p
                                 WHERE p.name = 'STCFN'
                                    || LPAD(ASCII(g.ch)::text, 3, '0')), 4)
             END) OVER (ORDER BY g.pos ROWS BETWEEN UNBOUNDED PRECEDING
                                             AND 1 PRECEDING) AS pen
  FROM message_glyphs g
),
message_pixels AS (
  SELECT COALESCE(mp.pen, 0)::int + px.dx AS x, 1 + px.dy AS y,
         px.palette_index
  FROM message_placed mp
  JOIN ui_hud_pixels px ON px.name = mp.patch
  WHERE mp.patch IS NOT NULL
),
view_lanes AS NOT MATERIALIZED (
  -- Every stream's lanes: sixteen pixels of a column a row (see
  -- wall_lanes). NOT MATERIALIZED: view_cells reads it too (for the debug
  -- overlay alone), and two readers would otherwise store its ~6,000 rows.
  -- A cell is x * 16 + g, one integer to group by. A pixel's resolve key is
  -- packed into one bigint, every field oriented so
  -- that smaller wins: depth first, then wall > sprite > plane, then the
  -- lower source_priority, then stable_id to keep exact ties from depending
  -- on input order:
  --   (depth*4096 << 34) | ((2 - surface) << 32) | (source << 30)
  --   | (stable_id + 32768 << 14) | (light_index << 8) | palette_index
  -- with surface 2 for walls, 1 for sprites and 0 for planes. Each stream
  -- builds its own keys, the parts that are constant along a span once per
  -- span. The weapon and the pickup message are drawn over the view
  -- regardless of depth: their keys are negative, which every view fragment
  -- (depth >= 0) loses to: the message beats the flash (layer 2), which beats
  -- the weapon (layer 1).
  SELECT x * 16 + g AS cell, k0, k1, k2, k3, k4, k5, k6, k7, k8, k9, k10, k11, k12, k13, k14, k15 FROM wall_lanes
  UNION ALL
  SELECT x * 16 + g AS cell, k0, k1, k2, k3, k4, k5, k6, k7, k8, k9, k10, k11, k12, k13, k14, k15 FROM sprite_lanes
  UNION ALL
  SELECT x * 16 + g AS cell, k0, k1, k2, k3, k4, k5, k6, k7, k8, k9, k10, k11, k12, k13, k14, k15 FROM plane_lanes
  UNION ALL
  SELECT x * 16 + g AS cell, k0, k1, k2, k3, k4, k5, k6, k7, k8, k9, k10, k11, k12, k13, k14, k15 FROM psprite_lanes
  UNION ALL
  SELECT x * 16 + g AS cell, k0, k1, k2, k3, k4, k5, k6, k7, k8, k9, k10, k11, k12, k13, k14, k15 FROM message_lanes
),
view_cells AS NOT MATERIALIZED (
  -- The nearest fragment of each pixel: its lane's MIN over the rows of its
  -- cell (sixteen pixels of a column), as view_words takes it for the
  -- frame: a HashAggregate of ~6,000 rows, where a sort of every fragment by
  -- pixel and a Unique took a third of the frame.
  -- A lane no fragment reached (a hole) stays NULL. NOT MATERIALIZED: only
  -- the debug overlay's counts read it twice (view_holes), and they store it.
  SELECT cell >> 4 AS x, cell & 15 AS g, MIN(k0) AS k0, MIN(k1) AS k1, MIN(k2) AS k2, MIN(k3) AS k3, MIN(k4) AS k4, MIN(k5) AS k5, MIN(k6) AS k6, MIN(k7) AS k7, MIN(k8) AS k8, MIN(k9) AS k9, MIN(k10) AS k10, MIN(k11) AS k11, MIN(k12) AS k12, MIN(k13) AS k13, MIN(k14) AS k14, MIN(k15) AS k15
  FROM view_lanes
  GROUP BY cell
),
-- Shotgun psprites
psprite_layers AS (
  SELECT 1 AS layer, wr.sprite, wr.frame::char(1) AS frame,
         wr.sx::double precision AS sx, wr.sy::double precision AS sy,
         COALESCE(wr.fullbright, FALSE) AS fullbright
  FROM weapon_runtime wr
  UNION ALL
  SELECT 2, wr.flash_sprite, wr.flash_frame::char(1) AS frame,
         wr.sx, wr.sy, COALESCE(wr.flash_fullbright, TRUE)
  FROM weapon_runtime wr
  WHERE wr.flash_sprite IS NOT NULL AND wr.flash_frame IS NOT NULL
),
psprite_patches AS MATERIALIZED (
  SELECT p.*, sf.width, sf.height, sf.left_offset, sf.top_offset,
         (sl.pixels || ''::bytea) AS pixels, (sl.mask || ''::bytea) AS mask,
         p.sx - sf.left_offset AS x_left_f,
         p.sy - sf.top_offset + rs.cy - 100.0 - 0.5 AS y_top_f
  FROM psprite_layers p
  CROSS JOIN render_settings rs
  JOIN sprite_frames sf ON sf.sprite=p.sprite AND sf.frame=p.frame
    AND sf.rotation=0
  JOIN sprite_lumps sl ON sl.lump_name=sf.lump_name
),
psprite_layer_keys AS (
  -- Each layer's box on screen and its key's high bits: the layer and its
  -- light, which is the layer's alone (the player's sector, the flash).
  SELECT p.pixels, p.mask, p.width,
         FLOOR(p.x_left_f)::int AS x0, FLOOR(p.y_top_f)::int AS y0,
         GREATEST(0, FLOOR(p.y_top_f)::int) AS ya,
         LEAST(rs.screen_h - 1, FLOOR(p.y_top_f)::int + p.height - 1) AS yb,
         ((-(p.layer::bigint + 1)) << 32)
         | ((CASE WHEN wr.invuln THEN rs.light_index_invuln
                  WHEN p.fullbright THEN 0
                  ELSE doom_light_index(ps.light_level, wr.extra_light,
                                        rs.light_psprite_bias)
             END)::bigint << 8) AS key_hi
  FROM psprite_patches p
  CROSS JOIN player_sector ps CROSS JOIN weapon_runtime wr
  CROSS JOIN render_settings rs
),
psprite_lanes AS (
  -- The weapon's pixels, sixteen of a column a row (see wall_lanes): the inner
  -- query finds each lane's offset into the patch (NULL off it), the outer
  -- keeps the opaque ones.
  SELECT q.x, q.g,
    CASE WHEN GET_BYTE(q.mask, q.o0) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o0)::bigint END AS k0,
    CASE WHEN GET_BYTE(q.mask, q.o1) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o1)::bigint END AS k1,
    CASE WHEN GET_BYTE(q.mask, q.o2) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o2)::bigint END AS k2,
    CASE WHEN GET_BYTE(q.mask, q.o3) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o3)::bigint END AS k3,
    CASE WHEN GET_BYTE(q.mask, q.o4) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o4)::bigint END AS k4,
    CASE WHEN GET_BYTE(q.mask, q.o5) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o5)::bigint END AS k5,
    CASE WHEN GET_BYTE(q.mask, q.o6) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o6)::bigint END AS k6,
    CASE WHEN GET_BYTE(q.mask, q.o7) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o7)::bigint END AS k7,
    CASE WHEN GET_BYTE(q.mask, q.o8) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o8)::bigint END AS k8,
    CASE WHEN GET_BYTE(q.mask, q.o9) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o9)::bigint END AS k9,
    CASE WHEN GET_BYTE(q.mask, q.o10) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o10)::bigint END AS k10,
    CASE WHEN GET_BYTE(q.mask, q.o11) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o11)::bigint END AS k11,
    CASE WHEN GET_BYTE(q.mask, q.o12) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o12)::bigint END AS k12,
    CASE WHEN GET_BYTE(q.mask, q.o13) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o13)::bigint END AS k13,
    CASE WHEN GET_BYTE(q.mask, q.o14) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o14)::bigint END AS k14,
    CASE WHEN GET_BYTE(q.mask, q.o15) <> 0 THEN q.key_hi | GET_BYTE(q.pixels, q.o15)::bigint END AS k15
  FROM (
    SELECT c.x, c.g, c.pixels, c.mask, c.key_hi,
           CASE WHEN (c.g*16+0) BETWEEN c.ya AND c.yb THEN ((c.g*16+0) - c.y0)*c.width + (c.x - c.x0) END AS o0,
           CASE WHEN (c.g*16+1) BETWEEN c.ya AND c.yb THEN ((c.g*16+1) - c.y0)*c.width + (c.x - c.x0) END AS o1,
           CASE WHEN (c.g*16+2) BETWEEN c.ya AND c.yb THEN ((c.g*16+2) - c.y0)*c.width + (c.x - c.x0) END AS o2,
           CASE WHEN (c.g*16+3) BETWEEN c.ya AND c.yb THEN ((c.g*16+3) - c.y0)*c.width + (c.x - c.x0) END AS o3,
           CASE WHEN (c.g*16+4) BETWEEN c.ya AND c.yb THEN ((c.g*16+4) - c.y0)*c.width + (c.x - c.x0) END AS o4,
           CASE WHEN (c.g*16+5) BETWEEN c.ya AND c.yb THEN ((c.g*16+5) - c.y0)*c.width + (c.x - c.x0) END AS o5,
           CASE WHEN (c.g*16+6) BETWEEN c.ya AND c.yb THEN ((c.g*16+6) - c.y0)*c.width + (c.x - c.x0) END AS o6,
           CASE WHEN (c.g*16+7) BETWEEN c.ya AND c.yb THEN ((c.g*16+7) - c.y0)*c.width + (c.x - c.x0) END AS o7,
           CASE WHEN (c.g*16+8) BETWEEN c.ya AND c.yb THEN ((c.g*16+8) - c.y0)*c.width + (c.x - c.x0) END AS o8,
           CASE WHEN (c.g*16+9) BETWEEN c.ya AND c.yb THEN ((c.g*16+9) - c.y0)*c.width + (c.x - c.x0) END AS o9,
           CASE WHEN (c.g*16+10) BETWEEN c.ya AND c.yb THEN ((c.g*16+10) - c.y0)*c.width + (c.x - c.x0) END AS o10,
           CASE WHEN (c.g*16+11) BETWEEN c.ya AND c.yb THEN ((c.g*16+11) - c.y0)*c.width + (c.x - c.x0) END AS o11,
           CASE WHEN (c.g*16+12) BETWEEN c.ya AND c.yb THEN ((c.g*16+12) - c.y0)*c.width + (c.x - c.x0) END AS o12,
           CASE WHEN (c.g*16+13) BETWEEN c.ya AND c.yb THEN ((c.g*16+13) - c.y0)*c.width + (c.x - c.x0) END AS o13,
           CASE WHEN (c.g*16+14) BETWEEN c.ya AND c.yb THEN ((c.g*16+14) - c.y0)*c.width + (c.x - c.x0) END AS o14,
           CASE WHEN (c.g*16+15) BETWEEN c.ya AND c.yb THEN ((c.g*16+15) - c.y0)*c.width + (c.x - c.x0) END AS o15
    FROM (SELECT l.*, generate_series(l.ya >> 4, l.yb >> 4) AS g
          FROM (SELECT k.pixels, k.mask, k.width, k.x0, k.y0, k.ya, k.yb, k.key_hi,
                       generate_series((GREATEST(0, k.x0)) + ((GREATEST(0, k.x0)) & 1), LEAST(rs.screen_w - 1, k.x0 + k.width - 1), 2) AS x
                FROM psprite_layer_keys k CROSS JOIN render_settings rs) l) c
    OFFSET 0
  ) q
),
message_lanes AS (
  -- The pickup message's pixels, one lane each.
  SELECT m.x, m.y >> 4 AS g,
         CASE WHEN (m.y & 15) = 0 THEN m.k END AS k0,
         CASE WHEN (m.y & 15) = 1 THEN m.k END AS k1,
         CASE WHEN (m.y & 15) = 2 THEN m.k END AS k2,
         CASE WHEN (m.y & 15) = 3 THEN m.k END AS k3,
         CASE WHEN (m.y & 15) = 4 THEN m.k END AS k4,
         CASE WHEN (m.y & 15) = 5 THEN m.k END AS k5,
         CASE WHEN (m.y & 15) = 6 THEN m.k END AS k6,
         CASE WHEN (m.y & 15) = 7 THEN m.k END AS k7,
         CASE WHEN (m.y & 15) = 8 THEN m.k END AS k8,
         CASE WHEN (m.y & 15) = 9 THEN m.k END AS k9,
         CASE WHEN (m.y & 15) = 10 THEN m.k END AS k10,
         CASE WHEN (m.y & 15) = 11 THEN m.k END AS k11,
         CASE WHEN (m.y & 15) = 12 THEN m.k END AS k12,
         CASE WHEN (m.y & 15) = 13 THEN m.k END AS k13,
         CASE WHEN (m.y & 15) = 14 THEN m.k END AS k14,
         CASE WHEN (m.y & 15) = 15 THEN m.k END AS k15
  FROM (SELECT mp.x, mp.y, ((-8)::bigint << 32) | mp.palette_index::bigint AS k
        FROM message_pixels mp CROSS JOIN render_settings rs
        WHERE mp.x BETWEEN 0 AND rs.screen_w - 1 AND mp.y BETWEEN 0 AND rs.screen_h - 1 AND (mp.x & 1) = 0) m
),
player_ui_state AS (
  SELECT ps.health, ps.alive, ps.pain_face_tics, ps.armor,
         ps.ammo_bullets, ps.ammo_shells, ps.ammo_rockets, ps.ammo_cells,
         ps.key_blue,ps.key_yellow,ps.key_red,
         ps.damage_count, ps.bonus_count, ps.radsuit_tics,
         ps.message, ps.message_tics, ps.backpack,
         wd.ammo_type AS current_ammo_type
  FROM me_state ps
  CROSS JOIN render_context rc
  LEFT JOIN player_weapons w ON w.map_id = ps.map_id
    AND w.player_thing_id = ps.player_thing_id
  LEFT JOIN weapon_defs wd ON wd.weapon_id = COALESCE(w.current_weapon, 2)
  WHERE ps.map_id = rc.map_id AND ps.player_thing_id = rc.player_thing_id
),
active_palette AS (
  -- ST_doPaletteStuff, verbatim:
  --   if (cnt)            palette = min((cnt+7)>>3, NUMREDPALS-1)   + STARTREDPALS
  --   else if (bonus)     palette = min((b+7)>>3, NUMBONUSPALS-1) + STARTBONUSPALS
  --   else if (ironfeet > 4*32 || ironfeet & 8)  palette = RADIATIONPAL
  --   else                palette = 0
  -- with STARTREDPALS 1, NUMREDPALS 8, STARTBONUSPALS 9, NUMBONUSPALS 4 and
  -- RADIATIONPAL 13. The & 8 is what makes the radiation suit's green blink
  -- as it runs out.
  SELECT CASE
    WHEN pu.damage_count > 0
      THEN LEAST(7, (pu.damage_count + 7) / 8) + 1
    WHEN pu.bonus_count > 0
      THEN LEAST(3, (pu.bonus_count + 7) / 8) + 9
    WHEN pu.radsuit_tics > 128 OR (pu.radsuit_tics & 8) <> 0
      THEN 13
    ELSE 0
  END::smallint AS pal
  FROM player_ui_state pu
),
weapon_ownership AS (
  SELECT slot.weapon_id,
         EXISTS (
           SELECT 1 FROM player_weapon_owned o CROSS JOIN render_context rc
           WHERE o.map_id=rc.map_id AND o.player_thing_id=rc.player_thing_id
             AND o.weapon_id=slot.weapon_id
         ) AS owned
  FROM generate_series(2,7) slot(weapon_id)
),
weapon_layers AS (
  -- Vanilla's ARMS panel shows weapon slots 2..7: gray while unavailable,
  -- yellow once owned. Fist/chainsaw share slot 1 and are not listed here.
  SELECT 2 AS layer,
         (CASE WHEN owned THEN 'STYSNUM' ELSE 'STGNUM' END)
           || weapon_id::text AS patch,
         111+((weapon_id-2)%3)*12 AS x,
         172+((weapon_id-2)/3)*10 AS y
  FROM weapon_ownership
),
ui_face AS (
  SELECT
    CASE
      WHEN NOT pu.alive THEN 'STFDEAD0'
      WHEN pu.pain_face_tics > 0 THEN
        'STFOUCH' || LEAST(4, GREATEST(0, (100 - GREATEST(0, LEAST(100, pu.health))) / 20))::text
      ELSE
        'STFST' || LEAST(4, GREATEST(0, (100 - GREATEST(0, LEAST(100, pu.health))) / 20))::text || '0'
    END AS face_patch
  FROM player_ui_state pu
),
status_bar AS NOT MATERIALIZED (
  SELECT
    rs.screen_h     AS top_y,
    rs.screen_h + 4 AS digit_y,
    90::int         AS health_right_x,
    221::int        AS armor_right_x,
    44::int         AS ammo_right_x,
    288::int        AS ammo_box_right_x,
    314::int        AS max_ammo_right_x,
    239::int        AS key_x,
    143::int        AS face_x,
    14::int         AS tall_digit_w,
    4::int          AS short_digit_w 
  FROM render_settings rs
),
health_digits AS (SELECT pu.health AS value, sb.health_right_x AS right_x
                  FROM player_ui_state pu CROSS JOIN status_bar sb),
armor_digits AS (SELECT pu.armor AS value, sb.armor_right_x AS right_x
                 FROM player_ui_state pu CROSS JOIN status_bar sb),
ammo_digits AS (
  SELECT
    CASE pu.current_ammo_type
      WHEN 'bullets' THEN pu.ammo_bullets WHEN 'shells' THEN pu.ammo_shells
      WHEN 'rockets' THEN pu.ammo_rockets WHEN 'cells' THEN pu.ammo_cells
    END AS value,
    sb.ammo_right_x AS right_x
  FROM player_ui_state pu CROSS JOIN status_bar sb
  WHERE pu.current_ammo_type IS NOT NULL
),
-- The small always-visible sub-box showing all 4 ammo types at once, independent of which
-- weapon is currently equipped.
ammo_type_values AS (
  SELECT pu.ammo_bullets AS value, sb.ammo_box_right_x AS right_x, 173 AS y
  FROM player_ui_state pu CROSS JOIN status_bar sb
  UNION ALL
  SELECT pu.ammo_shells, sb.ammo_box_right_x, 179
  FROM player_ui_state pu CROSS JOIN status_bar sb
  UNION ALL
  SELECT pu.ammo_rockets, sb.ammo_box_right_x, 185
  FROM player_ui_state pu CROSS JOIN status_bar sb
  UNION ALL
  SELECT pu.ammo_cells, sb.ammo_box_right_x, 191
  FROM player_ui_state pu CROSS JOIN status_bar sb
),
ammo_max_values AS (
  SELECT (CASE WHEN pu.backpack THEN ad.backpack_cap ELSE ad.cap END) AS value,
         sb.max_ammo_right_x AS right_x,
         (CASE ad.ammo_type WHEN 'bullets' THEN 173 WHEN 'shells' THEN 179
                            WHEN 'rockets' THEN 185 ELSE 191 END) AS y
  FROM player_ui_state pu CROSS JOIN status_bar sb
  CROSS JOIN ammo_defs ad
),
key_layers AS (
  SELECT 1 AS layer,'STKEYS0'::text AS patch,sb.key_x AS x,171 AS y
  FROM player_ui_state CROSS JOIN status_bar sb WHERE key_blue
  UNION ALL SELECT 1,'STKEYS1',sb.key_x,181
  FROM player_ui_state CROSS JOIN status_bar sb WHERE key_yellow
  UNION ALL SELECT 1,'STKEYS2',sb.key_x,191
  FROM player_ui_state CROSS JOIN status_bar sb WHERE key_red
),
digit_layers AS (
  -- Digits are right-aligned ending at right_x, one row of generate_series
  -- per character position. An integer's text is at most 11 characters, so
  -- the series runs to 11 and the WHERE keeps the real ones: the same rows,
  -- but a series bounded by length() is estimated at 1000 rows a call, which
  -- made the planner size the status bar's joins for a million pixels and
  -- spill them through 16 temp-file batches.
  SELECT 1 AS layer,
    'STTNUM' || substring(hd.value::text FROM gs.i FOR 1) AS patch,
    hd.right_x - (length(hd.value::text) - gs.i + 1) * sb.tall_digit_w AS x,
    sb.digit_y AS y
  FROM health_digits hd CROSS JOIN status_bar sb
  CROSS JOIN generate_series(1, 11) AS gs(i)
  WHERE gs.i <= length(hd.value::text)
  UNION ALL
  SELECT 1, 'STTNUM' || substring(ad.value::text FROM gs.i FOR 1) AS patch,
    ad.right_x - (length(ad.value::text) - gs.i + 1) * sb.tall_digit_w AS x,
    sb.digit_y AS y
  FROM armor_digits ad CROSS JOIN status_bar sb
  CROSS JOIN generate_series(1, 11) AS gs(i)
  WHERE gs.i <= length(ad.value::text)
  UNION ALL
  SELECT 1, 'STTNUM' || substring(am.value::text FROM gs.i FOR 1) AS patch,
    am.right_x - (length(am.value::text) - gs.i + 1) * sb.tall_digit_w AS x,
    sb.digit_y AS y
  FROM ammo_digits am CROSS JOIN status_bar sb
  CROSS JOIN generate_series(1, 11) AS gs(i)
  WHERE gs.i <= length(am.value::text)
  UNION ALL
  SELECT 1, 'STYSNUM' || substring(at.value::text FROM gs.i FOR 1) AS patch,
    at.right_x - (length(at.value::text) - gs.i + 1) * sb.short_digit_w AS x,
    at.y
  FROM ammo_type_values at CROSS JOIN status_bar sb
  CROSS JOIN generate_series(1, 11) AS gs(i)
  WHERE gs.i <= length(at.value::text)
  UNION ALL
  SELECT 1, 'STYSNUM' || substring(mx.value::text FROM gs.i FOR 1) AS patch,
    mx.right_x - (length(mx.value::text) - gs.i + 1) * sb.short_digit_w AS x,
    mx.y
  FROM ammo_max_values mx CROSS JOIN status_bar sb
  CROSS JOIN generate_series(1, 11) AS gs(i)
  WHERE gs.i <= length(mx.value::text)
),
ui_layers AS (
  SELECT layer, patch, x, y FROM digit_layers
  UNION ALL SELECT layer,patch,x,y FROM key_layers
  UNION ALL SELECT layer,patch,x,y FROM weapon_layers
  UNION ALL SELECT 1, face_patch, sb.face_x, sb.top_y
  FROM ui_face CROSS JOIN status_bar sb
),
ui_layer_patches AS MATERIALIZED (
  -- The ~28 patches the bar shows, placed: MATERIALIZED, or the planner
  -- reads their pixels first and looks each pixel's patch up again.
  SELECT l.layer,l.patch,l.x-p.left_offset AS dest_x,
         l.y-p.top_offset AS dest_y
  FROM ui_layers l
  JOIN ui_patches p ON p.name = l.patch
),
ui_pixels AS (
  SELECT ulp.layer,ulp.dest_x+px.dx AS x,ulp.dest_y+px.dy AS y,
         px.palette_index
  FROM ui_layer_patches ulp
  -- Each patch's own pixels by index: a few dozen probes instead of a hash
  -- join reading all 39,000 of the status bar art's. OFFSET 0 keeps the
  -- planner from turning it back into that join.
  CROSS JOIN LATERAL (SELECT p.dx, p.dy, p.palette_index FROM ui_hud_pixels p
                      WHERE p.name = ulp.patch OFFSET 0) px
),
ui_resolved AS (
  -- ARG_MAX(palette_index, layer) in CedarDB; layer and index packed into one
  -- MAX here. Only the pixels on the bar, numbered in its screen order: the
  -- grouping's sort is then the order the splice reads them in.
  SELECT (u.y - rs.screen_h) * rs.screen_w + u.x AS pix,
         (MAX(u.layer*256+u.palette_index)%256) AS palette_index
  FROM ui_pixels u CROSS JOIN render_settings rs
  WHERE u.x BETWEEN 0 AND rs.screen_w - 1
    AND u.y BETWEEN rs.screen_h AND rs.screen_h + 31
  GROUP BY 1
),
ui_overlay AS (
  -- The overlay's pixels, each in light level 0 of this frame's palette,
  -- read out of a string through a scalar subquery: joined, the palette
  -- was a nested loop per pixel.
  SELECT ur.pix,
         substring((SELECT pb.b FROM palette_level0 pb)
                   FROM ur.palette_index * octet_length('\x00'::bytea) + 1
                   FOR octet_length('\x00'::bytea)) AS rgb
  FROM ui_resolved ur
),
ui_bar_static AS MATERIALIZED (
  -- The bar's own art in this frame's palette, made at load time
  -- (ui_bar_bytes), and detoasted once here for the reason frame_walltex
  -- gives. No player, no palette, no bar.
  SELECT ub.idx || ''::bytea AS b
  FROM active_palette ap
  JOIN ui_bar_bytes ub ON ub.pal = ap.pal
),
ui_runs AS (
  -- The placed patches' opaque pixels as runs (ui_hud_runs, made at load
  -- time), each in light level 0 of this frame's palette and clipped to the
  -- bar: ~150 pieces where single pixels were ~2,000. pix is the run's first
  -- pixel in the bar's screen order, n its length.
  SELECT (r.y - rs.screen_h) * rs.screen_w + GREATEST(0, r.x) AS pix,
         LEAST(r.x + r.len, rs.screen_w) - GREATEST(0, r.x) AS n,
         substring(r.b FROM (GREATEST(0, r.x) - r.x) * pb.bpp + 1
                   FOR (LEAST(r.x + r.len, rs.screen_w) - GREATEST(0, r.x)) * pb.bpp) AS b
  FROM (SELECT ulp.dest_y + h.dy AS y, ulp.dest_x + h.dx AS x, h.len, h.b
        FROM ui_layer_patches ulp
        CROSS JOIN active_palette ap
        -- each patch's runs by index, for the reason ui_pixels gives
        CROSS JOIN LATERAL (SELECT hr.dy, hr.dx, hr.len, hr.idx AS b FROM ui_hud_runs hr
                            WHERE hr.pal = ap.pal AND hr.name = ulp.patch OFFSET 0) h) r
  CROSS JOIN render_settings rs
  CROSS JOIN palette_level0 pb
  WHERE r.y BETWEEN rs.screen_h AND rs.screen_h + 31
    AND r.x < rs.screen_w AND r.x + r.len > 0
),
ui_colored AS (
  -- The static bar with the overlay spliced in: per run, in screen order,
  -- the static bytes since the last one and then its own. Patches that
  -- overlap (no two of the bar's do, but a WAD could place them so) are
  -- resolved pixel by pixel instead, as ui_resolved says: a run that starts
  -- before the one before it ends shows them.
  SELECT CASE WHEN o.overlap THEN (SELECT b FROM ui_colored_px)
              WHEN o.n = 0 THEN st.b
              ELSE o.b || substring(st.b FROM o.last_end * pb.bpp + 1) END AS b
  FROM ui_bar_static st
  CROSS JOIN palette_level0 pb
  CROSS JOIN LATERAL (
    SELECT count(*) AS n, MAX(v.pix + v.n) AS last_end,
           COALESCE(bool_or(v.pix < v.prev_end), FALSE) AS overlap,
           string_agg(substring(st.b FROM v.prev_end * pb.bpp + 1
                                FOR (v.pix - v.prev_end) * pb.bpp) || v.b,
                      ''::bytea ORDER BY v.pix) AS b
    FROM (SELECT r.pix, r.n, r.b, LAG(r.pix + r.n, 1, 0) OVER (ORDER BY r.pix) AS prev_end
          FROM ui_runs r) v
  ) o
),
ui_colored_px AS (
  -- The overlay pixel by pixel, for a bar whose patches overlap: per
  -- overlay pixel, in screen order, the static run since the last one and
  -- then its own colour.
  SELECT CASE WHEN o.n = 0 THEN st.b
              ELSE o.b || substring(st.b FROM (o.last_pix + 1) * pb.bpp + 1) END AS b
  FROM ui_bar_static st
  CROSS JOIN palette_level0 pb
  CROSS JOIN LATERAL (
    SELECT count(*) AS n, MAX(v.pix) AS last_pix,
           string_agg(substring(st.b FROM (v.prev + 1) * pb.bpp + 1
                                FOR (v.pix - v.prev - 1) * pb.bpp)
                      || COALESCE(v.rgb, substring(st.b FROM v.pix * pb.bpp + 1 FOR pb.bpp)),
                      ''::bytea ORDER BY v.pix) AS b
    FROM (SELECT o.pix, o.rgb, LAG(o.pix, 1, -1) OVER (ORDER BY o.pix) AS prev
          FROM ui_overlay o) v
  ) o
),
palette_level0 AS MATERIALIZED (
  -- Light level 0 alone (768 bytes), for the status bar's overlay. A join
  -- can copy its rows, and the whole 49 KB palette string with them: that
  -- was 370 ms over the bar's 10240 pixels.
  SELECT substring(b FROM 1 FOR 256 * bpp) AS b, bpp FROM palette_bytes
),

palette_bytes AS MATERIALIZED (
  -- This frame's COLORMAP x PLAYPAL as one string: entry (light, index) at
  -- offset (light*256 + index) * bpp. A substring per pixel replaces
  -- CedarDB's join of every pixel against the colormap. The string is made
  -- once per palette at load time (colormap_bytes): built here, it was a
  -- sort and an aggregate of 8,704 rows every frame. (No player, or a
  -- palette the WAD lacks: all black.) || '' detoasts it once, for the
  -- reason frame_walltex gives.
  SELECT CASE WHEN cb.pal IS NULL THEN
           decode(repeat(encode('\x00'::bytea, 'hex'), 64 * 256), 'hex')
         ELSE cb.idx || ''::bytea END AS b,
         octet_length('\x00'::bytea) AS bpp
  FROM (SELECT) one
  LEFT JOIN active_palette ap ON TRUE
  LEFT JOIN colormap_bytes cb ON cb.pal = ap.pal
),
frame_colormap AS MATERIALIZED (
  -- This frame's COLORMAP as palette indices, whichever colour the frame
  -- is in: entry (light, index) at offset light*256 + index. The view is
  -- packed as indices (view_words) and turned to RGB at the end if need be.
  -- || '' detoasts it once, for the reason frame_walltex gives.
  SELECT COALESCE(cb.idx || ''::bytea, decode(repeat('00', 64 * 256), 'hex')) AS b
  FROM (SELECT) one
  LEFT JOIN active_palette ap ON TRUE
  LEFT JOIN colormap_bytes cb ON cb.pal = ap.pal
),
view_words AS (
  -- A cell's sixteen pixels resolved (view_cells' MIN per lane) and through
  -- COLORMAP, in the aggregate's own projection, a node fewer a cell; a hole
  -- is index 0. The palette is read through scalar subqueries, evaluated
  -- once a frame: a join would cost a pass per cell. The entry's number,
  -- light * 256 + texel, is the key's low 14 bits as they are. sh is where
  -- the cell's column goes in a row of its block: 8 * (7 - column).
  SELECT ((cell >> 7) << 4) | (cell & 15) AS block,
         (7 - ((cell >> 4) & 7)) << 3 AS sh,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k0) & 16383)::int), 0)::bigint AS b0,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k1) & 16383)::int), 0)::bigint AS b1,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k2) & 16383)::int), 0)::bigint AS b2,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k3) & 16383)::int), 0)::bigint AS b3,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k4) & 16383)::int), 0)::bigint AS b4,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k5) & 16383)::int), 0)::bigint AS b5,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k6) & 16383)::int), 0)::bigint AS b6,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k7) & 16383)::int), 0)::bigint AS b7,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k8) & 16383)::int), 0)::bigint AS b8,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k9) & 16383)::int), 0)::bigint AS b9,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k10) & 16383)::int), 0)::bigint AS b10,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k11) & 16383)::int), 0)::bigint AS b11,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k12) & 16383)::int), 0)::bigint AS b12,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k13) & 16383)::int), 0)::bigint AS b13,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k14) & 16383)::int), 0)::bigint AS b14,
         COALESCE(GET_BYTE((SELECT fc.b FROM frame_colormap fc), (MIN(k15) & 16383)::int), 0)::bigint AS b15
  FROM view_lanes
  WHERE ((cell >> 4) & 1) = 0
  GROUP BY cell
),
view_rows AS (
  -- A block is eight columns by sixteen rows. Lane j of each of its cells
  -- is row 16g+j, the cell's column one byte of it: so row word j is the OR of
  -- every cell's lane j shifted into its column's byte, left column in the
  -- high byte. The frame is row-major, the walls and the cells column-major:
  -- this is where the pixels are put in screen order, with no sort of them.
  SELECT block >> 4 AS c, block & 15 AS g,
         bit_or((b0 << sh) | (b0 << (sh - 8))) AS r0,
         bit_or((b1 << sh) | (b1 << (sh - 8))) AS r1,
         bit_or((b2 << sh) | (b2 << (sh - 8))) AS r2,
         bit_or((b3 << sh) | (b3 << (sh - 8))) AS r3,
         bit_or((b4 << sh) | (b4 << (sh - 8))) AS r4,
         bit_or((b5 << sh) | (b5 << (sh - 8))) AS r5,
         bit_or((b6 << sh) | (b6 << (sh - 8))) AS r6,
         bit_or((b7 << sh) | (b7 << (sh - 8))) AS r7,
         bit_or((b8 << sh) | (b8 << (sh - 8))) AS r8,
         bit_or((b9 << sh) | (b9 << (sh - 8))) AS r9,
         bit_or((b10 << sh) | (b10 << (sh - 8))) AS r10,
         bit_or((b11 << sh) | (b11 << (sh - 8))) AS r11,
         bit_or((b12 << sh) | (b12 << (sh - 8))) AS r12,
         bit_or((b13 << sh) | (b13 << (sh - 8))) AS r13,
         bit_or((b14 << sh) | (b14 << (sh - 8))) AS r14,
         bit_or((b15 << sh) | (b15 << (sh - 8))) AS r15
  FROM view_words
  GROUP BY block
),
view_bands AS (
  -- Screen rows 16g..16g+15 (the last band 160..167): each row the eight
  -- bytes of its word in every block of the band, left to right. One sort of
  -- the 440 blocks by (g, c) serves all sixteen aggregates, which read their
  -- input presorted.
  SELECT g, string_agg(int8send(r0), ''::bytea ORDER BY c)
         || string_agg(int8send(r1), ''::bytea ORDER BY c)
         || string_agg(int8send(r2), ''::bytea ORDER BY c)
         || string_agg(int8send(r3), ''::bytea ORDER BY c)
         || string_agg(int8send(r4), ''::bytea ORDER BY c)
         || string_agg(int8send(r5), ''::bytea ORDER BY c)
         || string_agg(int8send(r6), ''::bytea ORDER BY c)
         || string_agg(int8send(r7), ''::bytea ORDER BY c)
         || CASE WHEN g < 10
                 THEN string_agg(int8send(r8), ''::bytea ORDER BY c)
                   || string_agg(int8send(r9), ''::bytea ORDER BY c)
                   || string_agg(int8send(r10), ''::bytea ORDER BY c)
                   || string_agg(int8send(r11), ''::bytea ORDER BY c)
                   || string_agg(int8send(r12), ''::bytea ORDER BY c)
                   || string_agg(int8send(r13), ''::bytea ORDER BY c)
                   || string_agg(int8send(r14), ''::bytea ORDER BY c)
                   || string_agg(int8send(r15), ''::bytea ORDER BY c)
                 ELSE ''::bytea END AS b
  FROM view_rows
  GROUP BY g
),
view_index AS (
  -- The view, row by row. A block no fragment reached (64 holes) is missing
  -- from view_blocks and leaves the view short: then every block is taken
  -- from a full grid, the missing ones black. Only such a frame pays for
  -- the grid.
  SELECT CASE WHEN octet_length(v.b) = rs.screen_w * rs.screen_h THEN v.b
              ELSE (SELECT string_agg(int8send(CASE j.j WHEN 0 THEN r.r0 WHEN 1 THEN r.r1 WHEN 2 THEN r.r2 WHEN 3 THEN r.r3 WHEN 4 THEN r.r4 WHEN 5 THEN r.r5 WHEN 6 THEN r.r6 WHEN 7 THEN r.r7 WHEN 8 THEN r.r8 WHEN 9 THEN r.r9 WHEN 10 THEN r.r10 WHEN 11 THEN r.r11 WHEN 12 THEN r.r12 WHEN 13 THEN r.r13 WHEN 14 THEN r.r14 ELSE r.r15 END),
                                      ''::bytea ORDER BY bg.g, j.j, bc.c)
                    FROM generate_series(0, rs.screen_w / 8 - 1) AS bc(c)
                    CROSS JOIN generate_series(0, 10) AS bg(g)
                    CROSS JOIN generate_series(0, 15) AS j(j)
                    LEFT JOIN (SELECT vr.c, vr.g, vr.r0, vr.r1, vr.r2, vr.r3, vr.r4, vr.r5, vr.r6, vr.r7, vr.r8, vr.r9, vr.r10, vr.r11, vr.r12, vr.r13, vr.r14, vr.r15 FROM view_rows vr) r0x
                      ON r0x.c = bc.c AND r0x.g = bg.g
                    CROSS JOIN LATERAL (SELECT COALESCE(r0x.r0, 0) AS r0,
                                               COALESCE(r0x.r1, 0) AS r1,
                                               COALESCE(r0x.r2, 0) AS r2,
                                               COALESCE(r0x.r3, 0) AS r3,
                                               COALESCE(r0x.r4, 0) AS r4,
                                               COALESCE(r0x.r5, 0) AS r5,
                                               COALESCE(r0x.r6, 0) AS r6,
                                               COALESCE(r0x.r7, 0) AS r7,
                                               COALESCE(r0x.r8, 0) AS r8,
                                               COALESCE(r0x.r9, 0) AS r9,
                                               COALESCE(r0x.r10, 0) AS r10,
                                               COALESCE(r0x.r11, 0) AS r11,
                                               COALESCE(r0x.r12, 0) AS r12,
                                               COALESCE(r0x.r13, 0) AS r13,
                                               COALESCE(r0x.r14, 0) AS r14,
                                               COALESCE(r0x.r15, 0) AS r15) r
                    WHERE bg.g * 16 + j.j < rs.screen_h)
         END AS b
  FROM (SELECT string_agg(vb.b, ''::bytea ORDER BY vb.g) AS b FROM view_bands vb) v
  CROSS JOIN render_settings rs
),
view_holes AS (
  -- Any view pixel no fragment reached. The pipeline aims to cover all
  -- screen_w*screen_h of them and normally does, but coverage depends on
  -- per-column clip arithmetic over a float camera pose (about one pose in
  -- fifty leaves a few pixels). A hole is index 0 in view_words; this is the
  -- debug overlay's count of them (render_stats_tail.sql).
  SELECT bc.x * 8 + j AS pix
  FROM render_settings rs
  CROSS JOIN LATERAL generate_series(0, rs.screen_w - 1) AS bc(x)
  CROSS JOIN generate_series(0, 10) AS bg(g)
  CROSS JOIN generate_series(0, 15) AS j
  LEFT JOIN view_cells vc ON vc.x = bc.x AND vc.g = bg.g
  WHERE bg.g * 16 + j < rs.screen_h
    AND (ARRAY[vc.k0, vc.k1, vc.k2, vc.k3, vc.k4, vc.k5, vc.k6, vc.k7, vc.k8, vc.k9, vc.k10, vc.k11, vc.k12, vc.k13, vc.k14, vc.k15])[j + 1] IS NULL
),
rgb_bands AS (
  -- An RGB frame's bands (a pixel of three bytes): each row word's eight
  -- palette indices looked up in this frame's palette at light level 0,
  -- which holds every index's colour (colormap_rgb: an entry's colour is
  -- that of its mapped index at level 0). Only an RGB frame reads it.
  SELECT g, string_agg(substring(pl.b FROM (((r0 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r0 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r0 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r0 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r0 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r0 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r0 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r0 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
         || string_agg(substring(pl.b FROM (((r1 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r1 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r1 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r1 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r1 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r1 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r1 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r1 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
         || string_agg(substring(pl.b FROM (((r2 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r2 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r2 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r2 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r2 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r2 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r2 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r2 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
         || string_agg(substring(pl.b FROM (((r3 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r3 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r3 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r3 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r3 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r3 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r3 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r3 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
         || string_agg(substring(pl.b FROM (((r4 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r4 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r4 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r4 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r4 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r4 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r4 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r4 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
         || string_agg(substring(pl.b FROM (((r5 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r5 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r5 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r5 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r5 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r5 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r5 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r5 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
         || string_agg(substring(pl.b FROM (((r6 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r6 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r6 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r6 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r6 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r6 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r6 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r6 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
         || string_agg(substring(pl.b FROM (((r7 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r7 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r7 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r7 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r7 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r7 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r7 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r7 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
         || CASE WHEN g < 10
                 THEN string_agg(substring(pl.b FROM (((r8 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r8 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r8 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r8 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r8 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r8 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r8 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r8 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
                   || string_agg(substring(pl.b FROM (((r9 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r9 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r9 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r9 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r9 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r9 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r9 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r9 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
                   || string_agg(substring(pl.b FROM (((r10 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r10 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r10 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r10 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r10 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r10 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r10 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r10 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
                   || string_agg(substring(pl.b FROM (((r11 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r11 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r11 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r11 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r11 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r11 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r11 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r11 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
                   || string_agg(substring(pl.b FROM (((r12 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r12 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r12 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r12 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r12 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r12 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r12 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r12 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
                   || string_agg(substring(pl.b FROM (((r13 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r13 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r13 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r13 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r13 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r13 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r13 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r13 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
                   || string_agg(substring(pl.b FROM (((r14 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r14 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r14 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r14 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r14 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r14 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r14 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r14 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
                   || string_agg(substring(pl.b FROM (((r15 >> 56) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r15 >> 48) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r15 >> 40) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r15 >> 32) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r15 >> 24) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r15 >> 16) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r15 >> 8) & 255)::int) * pl.bpp + 1 FOR pl.bpp) || substring(pl.b FROM (((r15 >> 0) & 255)::int) * pl.bpp + 1 FOR pl.bpp), ''::bytea ORDER BY c)
                 ELSE ''::bytea END AS b
  FROM view_rows
  CROSS JOIN palette_level0 pl
  GROUP BY g
),
-- @stats-cut: doom_sql.prepare_render_stats() splices its own counting
-- projection in here, so the debug overlay's row counts are always measured
-- against this exact pipeline instead of a hand-kept copy of it.
frame AS (
  -- The 3D view owns rows 0..screen_h-1 and the status bar rows
  -- screen_h..199, so the frame is the view's rows in order followed by the
  -- bar's. The view is palette indices; an RGB frame takes its bands from
  -- rgb_bands, or, when a block is missing (holes), looks each index of the
  -- whole view up one by one.
  SELECT CASE WHEN octet_length('\x00'::bytea) = 1 THEN v.b
              WHEN (SELECT count(*) FROM view_rows) = 440
                THEN (SELECT string_agg(rb.b, ''::bytea ORDER BY rb.g) FROM rgb_bands rb)
              ELSE (SELECT string_agg(substring(pb.b FROM GET_BYTE(v.b, g.i) * pb.bpp + 1
                                                FOR pb.bpp), ''::bytea ORDER BY g.i)
                    FROM generate_series(0, rs.screen_w * rs.screen_h - 1) AS g(i)
                    CROSS JOIN palette_level0 pb)
         END
         || COALESCE(u.b, ''::bytea) AS frame_rgb
  FROM view_index v
  CROSS JOIN (SELECT (SELECT b FROM ui_colored) AS b) u
  CROSS JOIN render_settings rs
)
SELECT CASE WHEN EXISTS (SELECT 1 FROM pos) THEN (SELECT set_byte('\x00'::bytea, 0, ap.pal::int) FROM active_palette ap) || frame_rgb END AS frame_rgb FROM frame;
$view$::text$template$;
